We first construct the auxiliary RKHS function $f_{\mathrm{aux}}$ defined in Eq. \eqref{eq:f_aux} in the main text, and give an upper bound on $\|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}$. Let $r = \max\{ \lfloor s_x\rfloor, \lfloor s_o \rfloor\} + 1 $. For $\boldsymbol{\gamma} = (\gamma_1,\dots, \gamma_d)$, we define an \emph{approximate identity} \citep[Section 4.1.2]{Giné_Nickl_2015} $K_{\boldsymbol{\gamma}}: \mathbb{R}^{d}\to \mathbb{R}$ via
\begin{align} K_{\mathbf{1}}(\mathbf x) := \sum_{j=1}^r\binom{r}{j}(-1)^{1-j} \frac{1}{j^{d}}\left(\frac{2}{\pi}\right)^{\frac{d}{2}}  \exp\left( -2 \sum_{i=1}^{d} \frac{x_i^2}{j^2} \right) , \quad
    K_{\boldsymbol{\gamma}}(\mathbf x) :=  K_{\mathbf{1}}\left(\frac{\mathbf x}{\boldsymbol{\gamma}}\right)\prod_{i=1}^{d}\frac{1}{\gamma_i}
\end{align}
Note that Eq. \eqref{eq:K_function} reduces to \cite{eberts2013optimal}[Eq. (8)] when $\gamma_1 = \dots = \gamma_{d}$, $s_1 = \dots, s_{d}$. 
We define $K_{\gamma_x} : \mathbb{R}^{d_x}\to \mathbb{R}$ to be $K_{\boldsymbol{\gamma}_x}$ with $\boldsymbol{\gamma}_x = \left[\gamma_x, \ldots,\gamma_x\right]\in\mathbb{R}^{d_x}$ (note this agrees with Eq. \eqref{eq:K_function_main} in the main) and 
$K_{\gamma_o} : \mathbb{R}^{d_o}\to \mathbb{R}$ to be $K_{\boldsymbol{\gamma}_o}$ with $\boldsymbol{\gamma}_o = \left[\gamma_o, \ldots,\gamma_o\right]\in\mathbb{R}^{d_o}$. 
Define $\iota_{x, \gamma_x^{-1}}:\mathbb{R}^{d_x} \to \mathbb{R}$ as an indicator function of $\{\boldsymbol{\omega}_x: \|\boldsymbol{\omega}_x\| \leq \gamma_x^{-1}\}$. 

By the Young's Convolution Inequality and the fact that $\mathcal{F}$ is unitary, we have
\begin{align*}
    \left\|f_{\ast}(\cdot, \mathbf o)\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]\right\|_{L^2(\mathbb{R}^{d_x})} \leq \|f_{\ast}(\cdot, \mathbf o)\|_{L^1(\mathbb{R}^{d_x})} \|\iota_{x,\gamma_x^{-1}}\|_{L^2(\mathbb{R}^{d_x})}
\end{align*}
The right hand side is finite by \Cref{ass:f_ast} in the main text. Hence we apply the Fourier operator $\mathcal{F}$ to $f_{\ast}(\cdot, \mathbf o)\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]$ to find that, $(\forall \mathbf o\in \mathcal{O})$,
\begin{align*}
    \mathcal{F}[f_{\ast}(\cdot, \mathbf o)\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]] = \mathcal{F}[f_{\ast}(\cdot,\mathbf o)]\cdot \iota_{x,\gamma_x^{-1}}.
\end{align*}
Therefore, $f_{\ast}\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}] = f_{\ast, \mathrm{low}}$ where $f_{\ast, \mathrm{low}}$ is defined in Eq. \eqref{eq:f_ast_low}. We define $f_{\ast, \mathrm{high}} = f_{\ast} - f_{\ast, \mathrm{low}}$. Then we have, $(\forall \mathbf o\in \mathcal{O})$, 
\begin{align*}
    \mathcal{F}[f_{\ast, \mathrm{high}}(\cdot, \mathbf o)] = \mathcal{F}[f_{\ast}(\cdot, \mathbf o)] - \mathcal{F}[f_{\ast, \mathrm{low}}(\cdot, \mathbf o)]
\end{align*}
satisfies Eq. \eqref{eq:f_ast_high} in the main text. We let $f_{\mathrm{aux}}$ be as defined in Eq. \eqref{eq:f_aux} in the main text. We have
\begin{align} &\quad \|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}} 
    \\ &\leq \left\| f_{\ast} \ast K_{\gamma_o} \ast \mathcal{F}^{-1}[\iota_{x, \gamma_x^{-1}}] \right\|_{\mathcal{H}_{\gamma_x,\gamma_o}} + \left\| K_{\gamma_x} \ast K_{\gamma_o} \ast (f_{\ast} - f_{\ast, \mathrm{low}}) \right\|_{\mathcal{H}_{\gamma_x,\gamma_o}} \nonumber \\
    &\stackrel{(a)}{\leq} n^{\frac{1}{2} \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{L^2(\mathbb{R}^{d_x+d_o})} + n^{\frac{1}{2} \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}
    \|f_{\ast} - f_{\ast,\mathrm{low}} \|_{L^2(\mathbb{R}^{d_x+d_o})}  \nonumber \\
    &\stackrel{(b)}{\leq}  3 n^{\frac{1}{2} \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}.
\end{align}
In the above chain of derivations, $(a)$ holds by applying \Cref{lem:mixed_convolution} to the first term and applying \Cref{cor:hang_prop_4_obs_cov} to the second term, $(b)$ holds by $\|f_{\ast, \mathrm{low}}\|_{L^2(\mathbb{R}^{d_x+d_o})}\leq \|f_{\ast}\|_{L^2(\mathbb{R}^{d_x+d_o})} \leq 1$ by Plancherel's Theorem and \Cref{ass:f_ast}.
Notice that,
\begin{align} (\ast) := \left\|\left[\hat{f}_{\lambda}\right] - f_{\ast}\right\|_{L^2(P_{XO})} \leq \left\|\left[\hat{f}_{\lambda}\right] - f_{\mathrm{aux}} \right\|_{L^2(P_{XO})} + \left\|f_\ast - f_{\mathrm{aux}} \right\|_{L^2(P_{XO})} .
\end{align}
By definition of $\hat{f}_{\lambda}$ in Eq.~\eqref{eq:hat_f_lambda} in the main text, it satisfies 
\begin{align} \lambda \|\hat{f}_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \frac{1}{n}\sum_{i=1}^n \left(y_i - \left\langle f, \hat{F}_{\xi}(\mathbf z_i,\mathbf o_i) \otimes \phi_{\gamma_o}(o_i) \right\rangle_{\mathcal{H}_{\gamma_x,\gamma_o}} \right)^2 \leq \frac{1}{n}\sum_{i=1}^n y_i^2.
\end{align}
Notice that
\begin{align*}
    \frac{1}{n}\sum_{i=1}^{n}y_i^2 = \frac{1}{n}\sum_{i=1}^{n}((Tf_{\ast})(\mathbf z_i, \mathbf o_i) + \upsilon_i)^2  \lesssim 2 + \frac{2}{n}\sum_{i=1}^{n}\upsilon_i^2,
\end{align*}
where the inequality follows from 
\begin{align*}
    \|Tf_{\ast}\|_{L^{\infty}(\mathcal{Z}\times \mathcal{O})}\leq \|f_{\ast}\|_{L^{\infty}(\mathcal{X}\times \mathcal{O})} \leq \|f_{\ast}\|_{L^{\infty}(\mathbb{R}^{d_x+d_o})} \lesssim 1,
\end{align*}
by \Cref{ass:f_ast}. By \Cref{ass:subgaussian}, $\upsilon_1, \ldots, \upsilon_n$ are $n$ i.i.d. mean zero $\sigma$-sub-Gaussian random variables so $\upsilon_1^2, \ldots, \upsilon_n^2$ are $n$ i.i.d. $\sigma^2$-sub-exponential random variables~\citep[Lemma 2.7.6]{vershynin2018high} with mean $\mathbb{E}[\upsilon_1^2] < \infty$. By Exercise 2.7.10 (Centering) of \cite{vershynin2018high} we know that $\upsilon_1^2 - \mathbb{E}[\upsilon_1^2], \ldots, \upsilon_n^2 - \mathbb{E}[\upsilon_n^2]$ are $n$ i.i.d. $C\sigma^2$-sub-exponential random variables for some universal constant $C$. By \citet[Theorem 2.8.1 (Bernstein's inequality)]{vershynin2018high}, we have
\begin{align*}
    (\forall t\geq 0), \;P\left(\left|\sum_{i=1}^{n}\upsilon_i^2\right| \geq n\left(1+\mathbb{E}\left[\upsilon_i^2\right]\right)\right) \leq 2\exp\left(-c\min\left(\frac{n}{C^2\sigma^4}, \frac{n}{C\sigma^2}\right)\right),
\end{align*}
where $c$ is a universal constant. For a fixed $\tau\geq 1$, for sufficiently large $n\geq 1$, the above right hand side $\leq 2\exp(-\tau)$. Thus for a fixed $\tau\geq 1$, with $P^n$-probability $\geq 1 - 2e^{-\tau}$, for sufficiently large $n\geq 1$, we have
\begin{align*}
    \frac{1}{n}\sum_{i=1}^{n}y_i^2  \lesssim 2 + \frac{2}{n}\sum_{i=1}^{n}\upsilon_i^2 \leq 4 + 2\mathbb{E}\left[\upsilon_i^2\right].
\end{align*}
Under the same high probability event, from Eq.~\eqref{eq:trivial_bound}, using $\lambda = \frac{1}{n}$, we have
\begin{align} \|\hat{f}_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}} \lesssim \sqrt{4 + 2\mathbb{E}\left[\upsilon_i^2\right]}\sqrt{n}. 
\end{align}
Also, we have 
\begin{align} \|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}\leq 2\sqrt{n}
\end{align}
proved above in Eq.~\eqref{eq:f_aux_norm}. Continuing from Eq. \eqref{eq:appendix_ast_triangular}, we apply \Cref{lem:l2toprojected_illp} to $\|[\hat{f}_{\lambda}] - f_{\mathrm{aux}}\|_{L^2(P_{XO})}$, where we notice that $\hat{f}_{\lambda}, f_{\mathrm{aux}}\in \mathcal{H}_{\gamma_x,\gamma_o}$, and we use Eq. \eqref{eq:mean_y_squared_concentration} and Eq. \eqref{eq:appendix_f_aux_upper_sqrtn} to verify the assumption of that lemma. We find, with $P^n$-probability $\geq 1 - 2e^{-\tau}$,
\begin{small}
\begin{align*}
    (\ast) \leq \gamma_x^{-d_x\eta_0} (\log n)^{\frac{d_x\eta_0}{2}} \left\| T \left[\hat{f}_{\lambda}\right] -  T f_{\mathrm{aux}} \right\|_{L^2(P_{ZO})} + n^{-\frac{\frac{s_x}{d_x} }{1+(2 + \frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} + \left\|f_{\ast} -  f_{\mathrm{aux}} \right\|_{L^2(P_{XO})} .
\end{align*}
\end{small}
From Eq.~\eqref{eq:f_f_aux_diff}, $\|f_{\ast} -  f_{\mathrm{aux}}\|_{L^2(P_{XO})}$ can be upper bounded (up to a constant) by the second last term above and hence subsumed. 
Through a triangular inequality, we have with $P^n$-probability $\geq 1 - 2e^{-\tau}$,
\begin{align}
    (\ast) &\leq \gamma_x^{-d_x\eta_0} (\log n)^{\frac{d_x\eta_0}{2}} \left(\left\| T \left[\hat{f}_{\lambda}\right] -  T f_{\ast} \right\|_{L^2(P_{ZO})}  +  \left\| T f_\ast -  T f_{\mathrm{aux}} \right\|_{L^2(P_{ZO})}\right) \nonumber \\
    &\qquad \qquad + n^{-\frac{\frac{s_x}{d_x} }{1+(2 + \frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align}
We prove in Eq.~\eqref{eq:Tf_Tf_aux} in \Cref{sec:approx_main} that $
\left\| T f_\ast -  T f_{\mathrm{aux}} \right\|_{L^2(P_{ZO})} \leq n^{-\frac{\frac{s_x}{d_x}+\eta_1}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}$, so we continue from above to obtain, with $P^n$-probability $\geq 1 - 2e^{-\tau}$, 
\begin{align} (\ast) \lesssim \gamma_x^{-d_x\eta_0} (\log n)^{\frac{d_x\eta_0}{2}} \left\| T \left[\hat{f}_{\lambda}\right] -  T f_{\ast} \right\|_{L^2(P_{ZO})} + n^{-\frac{\frac{s_x}{d_x}+\eta_1 - \eta_0}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} (\log n)^{\frac{d_x\eta_0}{2}} .
\end{align}
Note the last term of Eq.~\eqref{eq:unprojected_amplified_projected_example} is subsumed by the second term above since $\eta_0 \geq \eta_1$.
Recall the definition of $\bar{f}_{\lambda}$ in Eq. \eqref{eq:bar_f_lambda_main} in the main text. Then, we have, through a triangular inequality, with $P^n$-probability $\geq 1 - 2e^{-\tau}$, the following holds
\begin{align*}
    (\ast) &\leq \gamma_x^{-d_x\eta_0} (\log n)^{\frac{d_x\eta_0}{2}} \left(\underbrace{\left\| T \left[\hat{f}_{\lambda}\right] -  T \left[\bar{f}_{\lambda}\right] \right\|_{L^2(P_{ZO})}}_{\text{Projected Stage I Error}} +  \underbrace{\left\| T \left[\bar{f}_{\lambda}\right] -  T f_{\ast} \right\|_{L^2(P_{ZO})}}_{\text{Projected Stage II Error}}\right) \\
    &\qquad + n^{-\frac{\frac{s_x}{d_x}+\eta_1 - \eta_0}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} (\log n)^{\frac{d_x\eta_0}{2}} .
\end{align*}
The projected stage I error can be upper bounded by \Cref{prop:projected_stage_one} as $ n > A_{\lambda,\tau}$ is satisfied for sufficiently large $n \geq 1$ proved in Eq.~\eqref{eq:n_large_than_A}. 
\begin{align*}
    \text{Projected Stage I Error} = \left\| T \left[\hat{f}_{\lambda}\right] -  T \left[\bar{f}_{\lambda}\right] \right\|_{L^2(P_{ZO})} \leq \tau n^{-\frac{\frac{s_x}{d_x}+\eta_1}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}
\end{align*}
holds with $P^{n+\tilde{n}}$-probability $\geq 1-  34e^{-\tau}$.
The projected stage II error can be upper bounded by \Cref{prop: projected upper rate}.
\begin{align*}
    \text{Projected Stage II Error} = \left\| T \left[\bar{f}_{\lambda}\right] -  T f_{\ast} \right\|_{L^2(P_{ZO})} \leq \tau n^{-\frac{\frac{s_x}{d_x}+\eta_1}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \cdot (\log n)^{\frac{d_x+d_o+1}{2}}
\end{align*}
holds with $P^n$-probability $\geq 1 - 4e^{-\tau}$. Combine the above two upper bounds, and we have
\begin{align} (\ast) = \left\|\left[\hat{f}_{\lambda}\right] - f_{\ast}\right\|_{L^2(P_{XO})} \leq \tau n^{-\frac{\frac{s_x}{d_x}+\eta_1-\eta_0}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} (\log n)^{\frac{d_x+d_o+1 + d_x\eta_0}{2}}
\end{align}
holds with $P^{n+\tilde{n}}$-probability $1 - 40e^{-\tau}$.  So the proof is concluded.

With the introduction of $\mathcal{H}_{FO}$ and the partial isometry $V:\mathcal{H}_{XO}\to \mathcal{H}_{FO}$ in \Cref{sec:defi_H_FO}, we define
\begin{align*}
    \hat{h}_{\lambda} &:= arg\,min_{h\in \mathcal{H}_{FO}}  \frac{1}{n}\sum_{i=1}^{n}  \left(y_i - \left\langle h, V\Big(\hat{F}_\xi (\mathbf z_i, \mathbf o_i)\otimes \phi_{\gamma_o}(\mathbf o_i) \Big) \right\rangle_{ \mathcal{H}_{FO}} \right) ^2 + \lambda \|h\|_{\mathcal{H}_{FO}}^2 \\
    \bar{h}_{\lambda} &= arg\,min_{h \in \mathcal{H}_{FO}}  \frac{1}{n}\sum_{i=1}^{n}  \left(y_i - \left\langle h, V \Big( F_\ast(\mathbf z_i, \mathbf o_i) \otimes \phi_{\gamma_o}(\mathbf o_i) \Big) \right\rangle_{ \mathcal{H}_{FO}} \right) ^2 + \lambda \|h\|_{\mathcal{H}_{FO}}^2 .
\end{align*}

We further define
\begin{align} \begin{aligned}
    \boldsymbol{\Phi}_{\hat{F}O} : \mathcal{H}_{FO} \to \mathbb{R}^{n} &= \left[V \left( \hat{F}_\xi(\mathbf z_1, \mathbf o_1) \otimes \phi_{\gamma_o}(\mathbf o_1) \right),\dots, V \left( \hat{F}_\xi (\mathbf z_n, \mathbf o_n) \otimes \phi_{\gamma_o}(\mathbf o_n) \right) \right]^{\ast}\\
    \boldsymbol{\Phi}_{FO} : \mathcal{H}_{FO} \to \mathbb{R}^{n} &= \left[V \left( F_{\ast}(\mathbf z_1, \mathbf o_1) \otimes \phi_{\gamma_o}(\mathbf o_1) \right) ,\dots, V \left( F_{\ast}(\mathbf z_n, \mathbf o_n) \otimes \phi_{\gamma_o}(\mathbf o_n) \right)  \right]^{\ast} \\
    \mathbf Y \in \mathbb{R}^n &, \quad \mathbf Y = [y_1, \ldots, y_n]^\top,
\end{aligned}
\end{align}
and the following operators on $\mathcal{H}_{FO}$
\begin{align*}
    C_{\hat{F} O} := \mathbb{E} \left[  V\left( \hat{F}_\xi(Z, O) \otimes \phi_{\gamma_o}(O) \right)  \otimes  V\left( \hat{F}_\xi(Z, O) \otimes \phi_{\gamma_o}(O) \right)  \right] , &\quad \hat{C}_{\hat{F}O} := \frac{1}{n} \boldsymbol{\Phi}_{\hat{F} O}^\ast \boldsymbol{\Phi}_{\hat{F} O} \\
    C_{F O} := \mathbb{E} \left[  V\left( F_\ast(Z, O) \otimes \phi_{\gamma_o}(O) \right)  \otimes  V\left( F_\ast(Z, O) \otimes \phi_{\gamma_o}(O) \right)  \right] , &\quad \hat{C}_{FO} := \frac{1}{n} \boldsymbol{\Phi}_{F O}^{\ast} \boldsymbol{\Phi}_{F O}.
\end{align*}

Hence, we have closed form expression for 
\begin{align} \hat{h}_{\lambda} = \frac{1}{n}\left( \hat{C}_{\hat{F} O} + \lambda \right)^{-1}\boldsymbol{\Phi}_{\hat{F} O}^\ast \mathbf Y, \quad \bar{h}_{\lambda} = \frac{1}{n}\left( \hat{C}_{F O} + \lambda \right)^{-1}\boldsymbol{\Phi}_{FO}^\ast \mathbf Y .
\end{align}

Firstly, by \citet[Eq. (2.14)]{vershynin2018high}, $P(|\upsilon|\geq t) \leq 2\exp(-\frac{ct^2}{\sigma^2})$ for some universal constant $c$. 
Define $\upsilon_i=y_i - (Tf_{\ast})(\mathbf z_i, \mathbf o_i)$ for stage II samples $\{\mathbf z_i, \mathbf o_i, y_i\}_{i=1}^n$. 
Hence
\begin{align*}
    &P^{n}\left( \{ \mathbf z_i, \mathbf o_i, y_i\}_{i=1}^n \in (\mathcal{Z} \times \mathcal{O} \times Y)^n : \max_i |\upsilon_i|\leq t\}\right)\\
    \geq & 1 - \sum_{i=1}^{n}P(|\upsilon_i|\geq t)\\
    \geq & 1 - 2\exp\left(\ln n - \frac{ct^2}{\sigma^2}\right).
\end{align*}
Hence, with $P^{n}$-probability $\geq 1 - 2\exp(-\hat{\rho})$, we have
\begin{align*}
    \max_{1\leq i\leq n}|\upsilon_i|\leq \sigma\sqrt{\frac{\ln n + \hat{\rho}}{c}}.
\end{align*}
By \Cref{ass:f_ast}, we have $\|Tf_{\ast}\|_{\infty}\leq \|f_{\ast}\|_{\infty}\leq 1$. For $n\geq 1$, we define
\begin{align*}
    M_n = 1 + \sigma\sqrt{\frac{\ln n + \hat{\rho}}{c}}.
\end{align*}
Hence $y_i \in [-M_n, M_n]$ for all $1\leq i\leq n$ with $P^n$-probability $\geq 1 - 2\exp(-\hat{\rho})$. 

Secondly, we verify the assumptions of \citet[Theorem 7.23]{steinwart2008support}. By \citet[Example 7.3]{steinwart2008support}, the \emph{supremum bound} is satisfied for $B = 4M_n^2$ and the \emph{variance bound} is satisfied for $V = 16M_n^2$ and $\nu=1$. 
Define $D_{ZO}=\{\mathbf z_i, \mathbf o_i\}_{i=1}^n$ and $L^2(D_{ZO})$ as the $L^2$ space with respect to the empirical data measure $D_{ZO}$. 
We are about to show that $(\forall n\geq 1) (\exists p\in (0,1))(\exists a\geq B = 4M_n^2)$ such that 
\begin{align} (\forall i\geq 1)\; \mathbb{E}_{D_{ZO}\sim P_{ZO}^{n}}e_i(\mathrm{id}:\mathcal{H}_{FO}\to L^2(D_{ZO}))\leq ai^{-\frac{1}{2p}}.
\end{align}
To this end, we invoke \citet[Corollary 7.31]{steinwart2008support}, \Cref{cor:entropy_bounded_obscov} and \Cref{lem:reduced_rkhs_entropy}. We conclude that, there exists a constant $c_p>0$ only depending on $p$, such that $(\forall i\geq 1) (\forall n\geq 1)$, we have
\begin{align*}
    &\mathbb{E}_{D_{ZO}\sim P^n_{ZO}}e_i(\mathrm{id}:\mathcal{H}_{FO}\hookrightarrow L^2(D_{ZO}))\\
    \leq & c_p(3C)^{\frac{1}{2p}}\left(\frac{d_x+d_o+1}{2ep}\right)^{\frac{d_x+d_o+1}{2p}}\left(\gamma_x^{d_x}\gamma_o^{d_o}\right)^{-\frac{1}{2p}}(\min\{i,n\})^{\frac{1}{2p}}i^{-\frac{1}{p}}\\
    \leq & c_p(3C)^{\frac{1}{2p}}\left(\frac{d_x+d_o+1}{2ep}\right)^{\frac{d_x+d_o+1}{2p}}\left(\gamma_x^{d_x}\gamma_o^{d_o}\right)^{-\frac{1}{2p}}i^{-\frac{1}{2p}}.
\end{align*}
We define a new constant $\tilde{c}_{p}:= c_p(3C)^{\frac{1}{2p}}\left(\frac{d_x+d_o+1}{2ep}\right)^{\frac{d_x+d_o+1}{2p}}$. Since for all $n\geq 1$, $\left(\gamma_x^{d_x}\gamma_o^{d_o}\right)^{-\frac{1}{2p}}\geq 1$, we set 
\begin{align*}
    a = \max\{4M_n^2, \tilde{c}_{p}\}\left(\gamma_x^{d_x}\gamma_o^{d_o}\right)^{-\frac{1}{2p}}
\end{align*}
in Eq. \eqref{eq:f_bar_lambda_hnorm_rts}, which satisfies $a \geq B = 4M_n^2$ for all $n\geq1$. 

We thus apply \citet[Theorem 7.23]{steinwart2008support} restricted to the probabilistic event where $y_i\in [-2M_n, 2M_n]$ for all $1\leq i\leq n$. 
We find, with $P^{n}$-probability $\geq 1 - 5\exp(-\hat{\rho})$, 
\begin{align*}
    &\lambda \|\bar{f}_{\lambda}\|^2_{\mathcal{H}_{XO}}\leq 9\left(\lambda \|f_0\|^2_{\mathcal{H}_{XO}} + \|T(f_0 - f_{\ast})\|^2_{L^2(P_{ZO})}\right) \\ & + K\left(\frac{\max\{4M_n^2, \tilde{c}_{p}\}^{2p}\gamma_x^{-d_x}\gamma_o^{-d_o}}{\lambda^p n}\right) + \frac{216M_n^2 \hat{\rho}}{n} + \frac{15B_0\hat{\rho}}{n}
\end{align*}
where $K\geq 1$ is a constant depending on $p, M_n$, $f_0\in \mathcal{H}_{\gamma_x,\gamma_o}$. $B_0\geq B$ is a constant that satisfies
\begin{align*}
    \|L\circ (Tf_{0})\|_{\infty} &:= \sup_{(\mathbf z,\mathbf o,y)\in \mathcal{Z}\times \mathcal{O}\times [-2M_n, 2M_n]}(y - (Tf_0)(\mathbf z,\mathbf o))^2 \leq B_0,
\end{align*}
By checking the dependence of $K$ on $p, M_n$ in the proof of \citet[Theorem 7.23]{steinwart2008support}, we find that $K\leq c(p)M_n^2$ for some constant $c(p)$ depending only on $p$. 
We choose $f_0 = f_{\lambda}$, where $f_{\lambda} \in \mathcal{H}_{\gamma_x,\gamma_o}$ is defined in Eq. \eqref{eq:f_lambda}. We have, since $Y = [-2M_n, 2M_n]$, 
\begin{align*}
    \|L\circ (Tf_{\lambda})\|_{\infty} = & \sup_{(\mathbf z,\mathbf o,y)\in \mathcal{Z}\times \mathcal{O}\times [-2M_n, 2M_n]} (y - (Tf_{\lambda})(\mathbf z,\mathbf o))^2 
    \leq  (2M_n + \|Tf_{\lambda}\|_{\infty})^2 \\ \leq & (2M_n + \|f_{\lambda\|_{\infty}})^2 \leq (2M_n + \|f_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}})^2 .
\end{align*}
We choose thus 
\begin{align*}
    B_0  = (2M_n + \|f_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}})^2 \geq 4M_n^2 = B.
\end{align*}

Hence we deduce from the above high probability inequality that
\begin{align*}
    &\lambda \|\bar{f}_{\lambda}\|^2_{\mathcal{H}_{XO}}\leq C\left(\lambda \|f_{\lambda}\|^2_{\mathcal{H}_{XO}} + \|T(f_{\lambda} - f_{\ast})\|^2_{L^2(P_{ZO})}\right) \\ & + C\left( M_n^{2+2p}\left(\frac{\max\{4, \tilde{c}_{p}\}^{2p}\gamma_x^{-d_x}\gamma_o^{-d_o}}{\lambda^p n}\right) + \frac{(M_n + \|f_{\lambda}\|_{\mathcal{H}_{XO}})^2 \hat{\rho}}{n}\right) .
\end{align*}
for some constant $C$ that is independent of $\lambda, M_n, n, \gamma_x,\gamma_o, B, V, \hat{\rho}$.

