We prove in Eq. \eqref{eq:f_bv_besov_norm_estimate} in the Supplementary that $\mathfrak{F}\subseteq \mathbb{U}(B^{s_x,s_o}_{2,\infty}(\mathbb{R}^{d_x+d_o})) \cap L^\infty(\mathbb{R}^{d_x+d_o}) \cap L^1(\mathbb{R}^{d_x+d_o}) \cap C^0(\mathbb{R}^{d_x+d_o}) \subseteq \mathfrak{S}$, satisfying \Cref{ass:f_ast}. 
For each $f_{\mathbf v} \in \mathfrak{F}$, we construct the conditional distribution $P_{\mathbf v}(\cdot\mid \mathbf z,\mathbf o) := \mathcal{N}((Tf_{\mathbf v})(\mathbf z,\mathbf o), \sigma^2)$ as the normal distribution on $\mathbb{R}$ with mean $(Tf_{\mathbf v})(\mathbf z,\mathbf o)$ and variance $\sigma^2$, such that $P_{\mathbf v}$ satisfies \Cref{ass:subgaussian}. Together with the marginal distribution $P_{ZO}$ over $\mathcal{Z}\times\mathcal{O}$, we have constructed a family of distributions $\{
P_{\mathbf v}, \mathbf v \in \{0,1\}^{|\mathcal{L}|}\}$ over $\mathcal{Z}\times\mathcal{O}\times\mathbb{R}$ with each $P_{\mathbf v}$ associated to a $f_{\mathbf v} \in \mathfrak{F}$.

Next, by the Gilbert-Varshamov Bound~\citep[Lemma 2.9]{Tsybakov}, we prove in Eq.~\eqref{eq:f_l2_separate} and Eq.~\eqref{eq:kl_upper_bound_small} in the Supplementary that there exists a subset $V_\mathfrak{K} \subseteq \{0,1\}^{|\mathcal{L}|}$ with 
$|V_\mathfrak{K}|\geq 2^{\frac{\mathcal{L}}{8}}$ such that for any $f_{\mathbf v}, f_{\mathbf v^\prime} \in \mathfrak{F}_{\mathrm{pruned}} = \{f_{\mathbf v}\mid \mathbf v\in V_\mathfrak{K}\}$, there is 
\begin{align*}
    \|f_{\mathbf v} - f_{\mathbf v'}\|^2_{L^2(P_{XO})} \geq 2^{-2\mathfrak{K}\underline{s}} \zeta^{-d_x}, \quad \mathrm{KL} \left(P_{\boldsymbol{v}}^{\otimes n}, P_{\boldsymbol{0}}^{\otimes n}\right) \leq n 2^{-2\mathfrak{K}\underline{s}(\frac{d_x}{s_x}\eta_1 + 1)} . 
\end{align*}
Therefore, we have established that the function class $\mathfrak{F}_{\mathrm{pruned}}$ satisfies all the three properties as desired, namely $\mathfrak{F}_{\mathrm{pruned}}\subset \mathfrak{G}$, functions $f_{\mathbf v} \in \mathfrak{F}_{\mathrm{pruned}}$ are well-separated in $L^2(P_{XO})$ yet statistically indistinguishable.

Let $\gamma\in (0,1)$ be arbitrary. Let $\epsilon  > 0$ be arbitrary. We define
\begin{align*}
    f_{\gamma, \epsilon}(\mathbf x,\mathbf o) &:= \mathcal{F}^{-1}\left[\mathbbm{1}[\|\boldsymbol{\omega}\|_2 \in [\gamma^{-1}, \gamma^{-1}+\epsilon]]\right](\mathbf x). 
\end{align*}

We have $f_{\gamma,\epsilon}\in \mathrm{LF}\left((\gamma^{-1} + \epsilon)^{-1}\right)\cap \mathrm{HF}(\gamma)\cap L^{\infty}(P_{XO})$. Since $P_{XO}$ admits a density function on $\mathcal{X}\times \mathcal{O}$, and $f_{\gamma,\epsilon}$ only vanishes on sets of null Lebesgue measure, we have $\|f_{\gamma,\epsilon}\|_{L^2(P_{XO})}\neq 0$. As imposed by \Cref{ass:T_contractivity} and \Cref{ass:T_frequency_ill_posedness}, we thus have
\begin{align*}
    c_0^{-1} \left(\gamma^{-1} + \epsilon\right)^{-d_x\eta_0}\|f_{\gamma,\epsilon}\|_{L^2(P_{XO})}
\leq \|Tf_{\gamma,\epsilon}\|_{L^2(P_{ZO})} \leq c_1 \gamma^{d_x\eta_1}\|f_{\gamma,\epsilon}\|_{L^2(P_{XO})}.
\end{align*}

Since $\|f_{\gamma,\epsilon}\|_{L^2(P_{XO})}\neq 0$, we have $(\forall \gamma\in (0,1))\;(\forall \epsilon >0)\; c_0^{-1}\left(\gamma^{-1} + \epsilon\right)^{-d_x\eta_0} \leq c_1 \gamma^{d_x\eta_1}$. For a fixed $\gamma$, taking the limit $\epsilon \to 0$, we have by continuity
\begin{align} (\forall \gamma\in (0,1))\; \frac{1}{c_0 c_1}\leq \gamma^{d_x(\eta_1-\eta_0)}.
\end{align}

\textbf{Stage 1}\quad We follow the closed-form solution given in \citet{lietal2022optimal}.  We define
\begin{align*}
    \boldsymbol{\Phi}_{\tilde{Z}\tilde{O}; 1}: \mathcal{H}_{ZO} \rightarrow \mathbb{R}^{\tilde{n}},& \quad  \boldsymbol{\Phi}_{\tilde{Z}\tilde{O};1} = \left[\phi_Z\left(\tilde{\mathbf z}_1\right) \otimes \phi_{O,1}\left(\tilde{\mathbf o}_1\right), \ldots, \phi_Z\left(\tilde{\mathbf z}_{\tilde{n}} \right) \otimes \phi_{O,1}(\tilde{\mathbf o}_{\tilde{n}})\right]^*, \\
    \boldsymbol{\Phi}_{\tilde{X}}: \mathcal{H}_X \rightarrow \mathbb{R}^{\tilde{n}},& \quad \boldsymbol{\Phi}_{\tilde{X}}=\left[\phi_X\left(\tilde{\mathbf x}_1\right), \ldots, \phi_X\left(\tilde{\mathbf x}_{\tilde{n}} \right)\right]^* 
\end{align*}
We obtain the following estimator
\begin{align} \hat{F}_{\xi}(\cdot, \cdot) = \hat{C}_{X\mid Z,O; \xi} \phi_{Z}(\cdot)\otimes \phi_{O,1}(\cdot),\quad 
    \hat{C}_{X\mid Z,O; \xi} = \boldsymbol{\Phi}_{\tilde{X}}^{\ast}\left(K_{\tilde{Z}\tilde{O};1} + \tilde{n}\xi\mathrm{Id}\right)^{-1}\boldsymbol{\Phi}_{\tilde{Z}\tilde{O}; 1},
\end{align}
where we introduce the Gram matrix
\begin{align*}
    K_{\tilde{Z}\tilde{O};1} = \boldsymbol{\Phi}_{\tilde{Z}\tilde{O};1}\boldsymbol{\Phi}_{\tilde{Z}\tilde{O};1}^{\ast}, \quad [K_{\tilde{Z}\tilde{O};1}]_{ij} = k_{Z}(\tilde{\mathbf z}_i, \tilde{\mathbf z}_j)k_{O,1}(\tilde{\mathbf o}_i, \tilde{\mathbf o}_j). 
\end{align*}

\textbf{Stage 2}\quad The Stage 2 solution can be written as 
\begin{align*}
    \hat{f}_{\lambda} = \left(\frac{1}{n}\boldsymbol{\Phi}_{\hat{F}O;2}^{\ast}\boldsymbol{\Phi}_{\hat{F}O;2} + \lambda\mathrm{Id}\right)^{-1}\frac{1}{n}\boldsymbol{\Phi}_{\hat{F}O;2}^{\ast}\mathbf{Y}
\end{align*}
where we define 
\begin{align*}
    \boldsymbol{\Phi}_{\hat{F}O;2} : \mathcal{H}_{XO}\to \mathbb{R}^n \quad \boldsymbol{\Phi}_{\hat{F}O;2}  = \left[\hat{F}_{\xi}(\mathbf z_1,\mathbf o_1)\otimes \phi_{O,2}(\mathbf o_1),\dots, \hat{F}_{\xi}(\mathbf z_n,\mathbf o_n)\otimes \phi_{O,2}(\mathbf o_n)\right]^{\ast}.
\end{align*}
We then write this in a dual form
\begin{align*}
    \hat{f}_{\lambda} = \boldsymbol{\Phi}_{\hat{F}O;2}^{\ast}\left(K_{\hat{F}O;2} + n\lambda\mathrm{Id}\right)^{-1}\mathbf{Y}.
\end{align*}
where we introduce the Gram matrix
\begin{align*}
    K_{\hat{F}O;2} = \boldsymbol{\Phi}_{\hat{F}O;2}\boldsymbol{\Phi}_{\hat{F}O;2}^{\ast}, \quad [K_{\hat{F}O;2}]_{ij} = \langle \hat{F}_{\xi}(\mathbf z_i,\mathbf o_i), \hat{F}_{\xi}(\mathbf z_j, \mathbf o_j)\rangle_{\mathcal{H}_{X}}k_{O,2}(\mathbf o_i, \mathbf o_j).
\end{align*}
By Eq.~\eqref{eq:closed_form_stage_1_estimator}, we obtain, for $1\leq j\leq n$,  
\begin{align} \hat{F}_{\xi}(\mathbf z_j, \mathbf o_j) = \boldsymbol{\Phi}_{\tilde{X}}^{\ast}\underbrace{\left(K_{\tilde{Z}\tilde{O},1} + \tilde{n}\xi\mathrm{Id}\right)^{-1}\left(K_{\tilde{Z}Z}\odot K_{\tilde{O}O;1}\right)_{: j}}_{=: J_{:j}} = \sum_{i=1}^{\tilde{n}}J_{ij}\phi_{X}(\tilde{\mathbf x}_i),
\end{align}
where $J$ as defined column-wise is a $\tilde{n}\times n$ matrix, and we define the (cross) Gram matrices
\begin{align*}
    [K_{\tilde{Z}Z}]_{ij} = k_{Z}(\tilde{\mathbf z}_i, \mathbf z_j),\quad [K_{\tilde{O}O;1}]_{ij} = k_{O,1}(\tilde{\mathbf o}_i, \mathbf o_j),
\end{align*}
for $1\leq i\leq \tilde{n}$, $1\leq j\leq n$. Consequently, for $1\leq i,j\leq n$,  we have
\begin{align*}
    K_{\hat{F}O;2} = \left(J^{T}K_{\tilde{X}\tilde{X}}J\right)\odot K_{OO;2},
\end{align*}
where we define the Gram matrices
\begin{align*}
    [K_{\tilde{X}\tilde{X}}]_{ij} = k_{X}(\tilde{\mathbf x}_{i}, \tilde{\mathbf x}_{j}), \quad [K_{OO;2}]_{lm} = k_{O,2}(\mathbf o_l, \mathbf o_m),
\end{align*}
for $1\leq i,j\leq \tilde{n}$, $1\leq l, m\leq n$. For a new test point $(\mathbf x,\mathbf o)\in \mathcal{X}\times \mathcal{O}$, we have, for $1\leq j\leq n$, 
\begin{align*}
    \left\langle \phi_{X}(\mathbf x)\otimes \phi_{O,2}(\mathbf o), \hat{F}_{\xi}(\mathbf z_j, \mathbf o_j)\otimes \phi_{O,2}(\mathbf o_j)\right\rangle_{\mathcal{H}_{XO}} &= k_{O,2}(\mathbf o, \mathbf o_j) \left(\sum_{i=1}^{\tilde{n}}J_{ij}k_{X}(\tilde{\mathbf x}_i, \mathbf x)\right)\\
    &= \left(K_{O\mathbf o,2}\odot (J^{T}K_{\tilde{X}\mathbf x})\right)_j, 
\end{align*}
where we define $K_{\tilde{X}\mathbf x} \in \mathbb{R}^{\tilde{n}\times 1}$ and $K_{O\mathbf o,2}\in \mathbb{R}^{n\times 1}$ respectively as follows: 
\begin{align*}
[K_{\tilde{X}\mathbf x}]_{i} = k_{X}(\tilde{\mathbf x}_i, \mathbf x),\quad [K_{O\mathbf o, 2}]_{i} = k_{O,2}(\mathbf o_i, \mathbf o).     
\end{align*}
Thus we have
\begin{align*}
    \hat{f}_{\lambda}(\mathbf x,\mathbf o) 
    &= \left\langle \phi_{X}(\mathbf x)\otimes \phi_{O,2}(\mathbf o), \boldsymbol{\Phi}_{\hat{F}O;2}^{\ast}\left(K_{\hat{F}O;2} + n\lambda \mathrm{Id}\right)^{-1}\mathbf{Y}\right\rangle_{\mathcal{H}_{XO}}\\
    &= \left(K_{O\mathbf o, 2}^{T} \odot (K_{\tilde{X}\mathbf x}^TJ)\right) \left(\left(J^{T}K_{\tilde{X}\tilde{X}}J\right)\odot K_{OO;2} + n\lambda \mathrm{Id}\right)^{-1}\mathbf{Y},
\end{align*}
where the last line follows by Eq.~\eqref{eq:closed_form_hat_F_xi}, 
Thus the derivation is concluded.

From \Cref{cor:CFO_evalue_entropy_bound} and \Cref{cor:entropy_bounded_obscov} and setting $p = \frac{1}{\log n}$, $(\forall i\geq 1)$, we have 
\begin{align*}
    \mu_{FO,i} \leq (C \log n)^{2(d_x+d_o+1) \log n}(\gamma_x^{d_x}\gamma_o^{d_o})^{-2\log n} i^{-2\log n}.
\end{align*}

Fix $i\geq 1$. For a Hilbert space $\mathcal{H}$, $B_{\mathcal{H}}$ denotes the unit ball in $\mathcal{H}$, and $B(x, r, \|\cdot \|_{\mathcal{H}})$ denotes the ball in $\mathcal{H}$ centred at $x\in\mathcal{H}$ with radius $r$. Fix $\epsilon>0$ such that $\exists g_1, \dots, g_{2^{i-1}} \in B_{\mathcal{H}_{\gamma_x,\gamma_o}}$ such that 
\begin{align*}
    B_{\mathcal{H}_{\gamma_x,\gamma_o}} \subseteq \bigcup_{i=1}^{2^{i-1}}B\left(g_i, \epsilon, \|\cdot \|_{L^2(P_{XO})}\right).
\end{align*}

Fix $f\in B_{\mathcal{H}_{FO}}$ and an arbitrary $\tilde{\epsilon}>0$. By \citet[Eq. (4.11)]{steinwart2008support}, there exists $g\in \mathcal{H}_{\gamma_x,\gamma_o}$ such that 
\begin{align*}
    f = \langle g, F_{\ast}(\cdot, \cdot)\otimes \phi_{\gamma_o}(\cdot)\rangle_{\mathcal{H}_{\gamma_x,\gamma_o}} = Vg,
\end{align*}
and $\|g\|_{\mathcal{H}_{\gamma_x,\gamma_o}}\leq 1 + \tilde{\epsilon}$. By the preceding statement, $(\exists i\in \{1,\dots, 2^{i-1}\})$ such that 
\begin{align*}
    \|g - (1+\tilde{\epsilon})g_i\|_{L^2(P_{XO})}\leq \epsilon(1 + \tilde{\epsilon}).
\end{align*}

For $i\in \{1,\dots, 2^{i-1}\}$, define $f_i = (1+\tilde{\epsilon})Vg_i = (1+\tilde{\epsilon})\langle g_i, F_{\ast}(\cdot, \cdot)\otimes \phi_{\gamma_o}(\cdot)\rangle_{\mathcal{H}_{\gamma_x,\gamma_o}}$. Then we have
\begin{align*}
    \|f - f_i\|^2_{L^2(P_{ZO})} &= \int_{\mathcal{Z}\times \mathcal{O}}\langle g - (1+\tilde{\epsilon})g_i, F_{\ast}(\mathbf z,\mathbf o)\otimes \phi_{\gamma_o}(\mathbf o)\rangle_{\mathcal{H}_{\gamma_x,\gamma_o}}^2p(\mathbf z,\mathbf o)\;\mathrm{d}\mathbf z\;\mathrm{d}\mathbf o\\
    &= \int_{\mathcal{Z}\times \mathcal{O}}\mathbb{E}[(g-(1+\tilde{\epsilon})g_i)(X,O)\mid Z = \mathbf z,O = \mathbf o]^2p(\mathbf z,\mathbf o)\;\mathrm{d}\mathbf z\;\mathrm{d}\mathbf o\\
    &\leq \|g - (1+\tilde{\epsilon}) g_i\|^2_{L^2(P_{XO})},
\end{align*}
where the inequality is deduced by Jensen's inequality. We find thus that 
\begin{align*}
    \mathcal{H}_{B_{FO}}\subseteq \bigcup_{i=1}^{2^{i-1}}B(f_i, \epsilon(1+\tilde{\epsilon}), \|\cdot\|_{L^2(P_{ZO})}).
\end{align*}

By \Cref{lem:hfo_conts_embedding}, we have $[\mathcal{H}_{FO}]_{L^2(\mathcal{Z}\times \mathcal{O})} \hookrightarrow MW^{m_z,m_o}(\mathcal{Z}\times \mathcal{O})$ and
\begin{align*}
    \| [\mathcal{H}_{FO}]_{L^2(\mathcal{Z}\times \mathcal{O})} \hookrightarrow MW^{m_z,m_o}(\mathcal{Z}\times \mathcal{O})\| \lesssim \rho  \gamma_o^{-m_o}.
\end{align*}

By \Cref{lem:anisotropic_sobolev_embedding}, since $\frac{d_o}{2s_o}<1$ and $\frac{d_z}{2s_z}<1$, we have $MW^{\theta m_z, \theta m_o}(\mathcal{Z}\times \mathcal{O})\hookrightarrow L^{\infty}(\mathcal{Z}\times \mathcal{O})$, with embedding norm a universal constant independent of $n$.  By Lemma \ref{lem:embedintosobolevimplies}, we thus have $(L^2(\mathcal{Z}\times \mathcal{O}), [\mathcal{H}_{FO}]_{L^2(\mathcal{Z}\times \mathcal{O})})_{\theta,2}\hookrightarrow L^{\infty}(\mathcal{Z}\times \mathcal{O})$ and 
\begin{align*}
    \| (L^2(\mathcal{Z}\times \mathcal{O}), [\mathcal{H}_{FO}]_{L^2(\mathcal{Z}\times\mathcal{O})})_{\theta,2}\hookrightarrow L^{\infty}(\mathcal{Z}\times \mathcal{O})\| \lesssim \rho^{\theta}  \gamma_o^{-\theta m_o},
\end{align*}

Next, since we know by Assumption~\ref{assn: technical} that $P_{ZO}$ is equivalent to Lebesgue measure on $\mathcal{Z}\times \mathcal{O}$, \Cref{lem:interpolation_equiv_measure} shows that we have 
\begin{align}
    \left(L^2(P_{ZO}), [\mathcal{H}_{FO}]_{L^2(P_{ZO})}\right)_{\theta,2}\hookrightarrow \left(L^2(\mathcal{Z}\times \mathcal{O}), [\mathcal{H}_{FO}]_{L^2(\mathcal{Z}\times \mathcal{O})}\right)_{\theta,2} \hookrightarrow L^{\infty}(P_{ZO})\nonumber,
\end{align}
and we have
\begin{align} \left\|\left(L^2(P_{ZO}), [\mathcal{H}_{FO}]_{L^2(P_{ZO})}\right)_{\theta,2}  \hookrightarrow L^{\infty}(P_{ZO})\right\| \lesssim \rho^{\theta}\gamma_o^{-\theta m_o}
\end{align}

We first construct the auxiliary RKHS function $f_{\mathrm{aux}}$ defined in Eq. \eqref{eq:f_aux} in the main text, and give an upper bound on $\|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}$. Let $r = \max\{ \lfloor s_x\rfloor, \lfloor s_o \rfloor\} + 1 $. For $\boldsymbol{\gamma} = (\gamma_1,\dots, \gamma_d)$, we define an \emph{approximate identity} \citep[Section 4.1.2]{Giné_Nickl_2015} $K_{\boldsymbol{\gamma}}: \mathbb{R}^{d}\to \mathbb{R}$ via
\begin{align} K_{\mathbf{1}}(\mathbf x) := \sum_{j=1}^r\binom{r}{j}(-1)^{1-j} \frac{1}{j^{d}}\left(\frac{2}{\pi}\right)^{\frac{d}{2}}  \exp\left( -2 \sum_{i=1}^{d} \frac{x_i^2}{j^2} \right) , \quad
    K_{\boldsymbol{\gamma}}(\mathbf x) :=  K_{\mathbf{1}}\left(\frac{\mathbf x}{\boldsymbol{\gamma}}\right)\prod_{i=1}^{d}\frac{1}{\gamma_i}
\end{align}
Note that Eq. \eqref{eq:K_function} reduces to \cite{eberts2013optimal}[Eq. (8)] when $\gamma_1 = \dots = \gamma_{d}$, $s_1 = \dots, s_{d}$. 
We define $K_{\gamma_x} : \mathbb{R}^{d_x}\to \mathbb{R}$ to be $K_{\boldsymbol{\gamma}_x}$ with $\boldsymbol{\gamma}_x = \left[\gamma_x, \ldots,\gamma_x\right]\in\mathbb{R}^{d_x}$ (note this agrees with Eq. \eqref{eq:K_function_main} in the main) and 
$K_{\gamma_o} : \mathbb{R}^{d_o}\to \mathbb{R}$ to be $K_{\boldsymbol{\gamma}_o}$ with $\boldsymbol{\gamma}_o = \left[\gamma_o, \ldots,\gamma_o\right]\in\mathbb{R}^{d_o}$. 
Define $\iota_{x, \gamma_x^{-1}}:\mathbb{R}^{d_x} \to \mathbb{R}$ as an indicator function of $\{\boldsymbol{\omega}_x: \|\boldsymbol{\omega}_x\| \leq \gamma_x^{-1}\}$. 

By the Young's Convolution Inequality and the fact that $\mathcal{F}$ is unitary, we have
\begin{align*}
    \left\|f_{\ast}(\cdot, \mathbf o)\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]\right\|_{L^2(\mathbb{R}^{d_x})} \leq \|f_{\ast}(\cdot, \mathbf o)\|_{L^1(\mathbb{R}^{d_x})} \|\iota_{x,\gamma_x^{-1}}\|_{L^2(\mathbb{R}^{d_x})}
\end{align*}
The right hand side is finite by \Cref{ass:f_ast} in the main text. Hence we apply the Fourier operator $\mathcal{F}$ to $f_{\ast}(\cdot, \mathbf o)\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]$ to find that, $(\forall \mathbf o\in \mathcal{O})$,
\begin{align*}
    \mathcal{F}[f_{\ast}(\cdot, \mathbf o)\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]] = \mathcal{F}[f_{\ast}(\cdot,\mathbf o)]\cdot \iota_{x,\gamma_x^{-1}}.
\end{align*}
Therefore, $f_{\ast}\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}] = f_{\ast, \mathrm{low}}$ where $f_{\ast, \mathrm{low}}$ is defined in Eq. \eqref{eq:f_ast_low}. We define $f_{\ast, \mathrm{high}} = f_{\ast} - f_{\ast, \mathrm{low}}$. Then we have, $(\forall \mathbf o\in \mathcal{O})$, 
\begin{align*}
    \mathcal{F}[f_{\ast, \mathrm{high}}(\cdot, \mathbf o)] = \mathcal{F}[f_{\ast}(\cdot, \mathbf o)] - \mathcal{F}[f_{\ast, \mathrm{low}}(\cdot, \mathbf o)]
\end{align*}
satisfies Eq. \eqref{eq:f_ast_high} in the main text. We let $f_{\mathrm{aux}}$ be as defined in Eq. \eqref{eq:f_aux} in the main text. We have
\begin{align} &\quad \|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}} 
    \\ &\leq \left\| f_{\ast} \ast K_{\gamma_o} \ast \mathcal{F}^{-1}[\iota_{x, \gamma_x^{-1}}] \right\|_{\mathcal{H}_{\gamma_x,\gamma_o}} + \left\| K_{\gamma_x} \ast K_{\gamma_o} \ast (f_{\ast} - f_{\ast, \mathrm{low}}) \right\|_{\mathcal{H}_{\gamma_x,\gamma_o}} \nonumber \\
    &\stackrel{(a)}{\leq} n^{\frac{1}{2} \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{L^2(\mathbb{R}^{d_x+d_o})} + n^{\frac{1}{2} \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}
    \|f_{\ast} - f_{\ast,\mathrm{low}} \|_{L^2(\mathbb{R}^{d_x+d_o})}  \nonumber \\
    &\stackrel{(b)}{\leq}  3 n^{\frac{1}{2} \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}.
\end{align}
In the above chain of derivations, $(a)$ holds by applying \Cref{lem:mixed_convolution} to the first term and applying \Cref{cor:hang_prop_4_obs_cov} to the second term, $(b)$ holds by $\|f_{\ast, \mathrm{low}}\|_{L^2(\mathbb{R}^{d_x+d_o})}\leq \|f_{\ast}\|_{L^2(\mathbb{R}^{d_x+d_o})} \leq 1$ by Plancherel's Theorem and \Cref{ass:f_ast}.

Notice that,
\begin{align} (\ast) := \left\|\left[\hat{f}_{\lambda}\right] - f_{\ast}\right\|_{L^2(P_{XO})} \leq \left\|\left[\hat{f}_{\lambda}\right] - f_{\mathrm{aux}} \right\|_{L^2(P_{XO})} + \left\|f_\ast - f_{\mathrm{aux}} \right\|_{L^2(P_{XO})} .
\end{align}

By definition of $\hat{f}_{\lambda}$ in Eq.~\eqref{eq:hat_f_lambda} in the main text, it satisfies 
\begin{align} \lambda \|\hat{f}_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \frac{1}{n}\sum_{i=1}^n \left(y_i - \left\langle f, \hat{F}_{\xi}(\mathbf z_i,\mathbf o_i) \otimes \phi_{\gamma_o}(o_i) \right\rangle_{\mathcal{H}_{\gamma_x,\gamma_o}} \right)^2 \leq \frac{1}{n}\sum_{i=1}^n y_i^2.
\end{align}
Notice that
\begin{align*}
    \frac{1}{n}\sum_{i=1}^{n}y_i^2 = \frac{1}{n}\sum_{i=1}^{n}((Tf_{\ast})(\mathbf z_i, \mathbf o_i) + \upsilon_i)^2  \lesssim 2 + \frac{2}{n}\sum_{i=1}^{n}\upsilon_i^2,
\end{align*}
where the inequality follows from 
\begin{align*}
    \|Tf_{\ast}\|_{L^{\infty}(\mathcal{Z}\times \mathcal{O})}\leq \|f_{\ast}\|_{L^{\infty}(\mathcal{X}\times \mathcal{O})} \leq \|f_{\ast}\|_{L^{\infty}(\mathbb{R}^{d_x+d_o})} \lesssim 1,
\end{align*}
by \Cref{ass:f_ast}. By \Cref{ass:subgaussian}, $\upsilon_1, \ldots, \upsilon_n$ are $n$ i.i.d. mean zero $\sigma$-sub-Gaussian random variables so $\upsilon_1^2, \ldots, \upsilon_n^2$ are $n$ i.i.d. $\sigma^2$-sub-exponential random variables~\citep[Lemma 2.7.6]{vershynin2018high} with mean $\mathbb{E}[\upsilon_1^2] < \infty$. By Exercise 2.7.10 (Centering) of \cite{vershynin2018high} we know that $\upsilon_1^2 - \mathbb{E}[\upsilon_1^2], \ldots, \upsilon_n^2 - \mathbb{E}[\upsilon_n^2]$ are $n$ i.i.d. $C\sigma^2$-sub-exponential random variables for some universal constant $C$. By \citet[Theorem 2.8.1 (Bernstein's inequality)]{vershynin2018high}, we have
\begin{align*}
    (\forall t\geq 0), \;P\left(\left|\sum_{i=1}^{n}\upsilon_i^2\right| \geq n\left(1+\mathbb{E}\left[\upsilon_i^2\right]\right)\right) \leq 2\exp\left(-c\min\left(\frac{n}{C^2\sigma^4}, \frac{n}{C\sigma^2}\right)\right),
\end{align*}
where $c$ is a universal constant. For a fixed $\tau\geq 1$, for sufficiently large $n\geq 1$, the above right hand side $\leq 2\exp(-\tau)$. Thus for a fixed $\tau\geq 1$, with $P^n$-probability $\geq 1 - 2e^{-\tau}$, for sufficiently large $n\geq 1$, we have
\begin{align*}
    \frac{1}{n}\sum_{i=1}^{n}y_i^2  \lesssim 2 + \frac{2}{n}\sum_{i=1}^{n}\upsilon_i^2 \leq 4 + 2\mathbb{E}\left[\upsilon_i^2\right].
\end{align*}
Under the same high probability event, from Eq.~\eqref{eq:trivial_bound}, using $\lambda = \frac{1}{n}$, we have
\begin{align} \|\hat{f}_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}} \lesssim \sqrt{4 + 2\mathbb{E}\left[\upsilon_i^2\right]}\sqrt{n}. 
\end{align}

Also, we have 
\begin{align} \|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}\leq 2\sqrt{n}
\end{align}
proved above in Eq.~\eqref{eq:f_aux_norm}. Continuing from Eq. \eqref{eq:appendix_ast_triangular}, we apply \Cref{lem:l2toprojected_illp} to $\|[\hat{f}_{\lambda}] - f_{\mathrm{aux}}\|_{L^2(P_{XO})}$, where we notice that $\hat{f}_{\lambda}, f_{\mathrm{aux}}\in \mathcal{H}_{\gamma_x,\gamma_o}$, and we use Eq. \eqref{eq:mean_y_squared_concentration} and Eq. \eqref{eq:appendix_f_aux_upper_sqrtn} to verify the assumption of that lemma. We find, with $P^n$-probability $\geq 1 - 2e^{-\tau}$,
\begin{small}
\begin{align*}
    (\ast) \leq \gamma_x^{-d_x\eta_0} (\log n)^{\frac{d_x\eta_0}{2}} \left\| T \left[\hat{f}_{\lambda}\right] -  T f_{\mathrm{aux}} \right\|_{L^2(P_{ZO})} + n^{-\frac{\frac{s_x}{d_x} }{1+(2 + \frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} + \left\|f_{\ast} -  f_{\mathrm{aux}} \right\|_{L^2(P_{XO})} .
\end{align*}
\end{small}

From Eq.~\eqref{eq:f_f_aux_diff}, $\|f_{\ast} -  f_{\mathrm{aux}}\|_{L^2(P_{XO})}$ can be upper bounded (up to a constant) by the second last term above and hence subsumed. 
Through a triangular inequality, we have with $P^n$-probability $\geq 1 - 2e^{-\tau}$,
\begin{align}
    (\ast) &\leq \gamma_x^{-d_x\eta_0} (\log n)^{\frac{d_x\eta_0}{2}} \left(\left\| T \left[\hat{f}_{\lambda}\right] -  T f_{\ast} \right\|_{L^2(P_{ZO})}  +  \left\| T f_\ast -  T f_{\mathrm{aux}} \right\|_{L^2(P_{ZO})}\right) \nonumber \\
    &\qquad \qquad + n^{-\frac{\frac{s_x}{d_x} }{1+(2 + \frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align}

Recall the definition of $\bar{f}_{\lambda}$ in Eq. \eqref{eq:bar_f_lambda_main} in the main text. Then, we have, through a triangular inequality, with $P^n$-probability $\geq 1 - 2e^{-\tau}$, the following holds
\begin{align*}
    (\ast) &\leq \gamma_x^{-d_x\eta_0} (\log n)^{\frac{d_x\eta_0}{2}} \left(\underbrace{\left\| T \left[\hat{f}_{\lambda}\right] -  T \left[\bar{f}_{\lambda}\right] \right\|_{L^2(P_{ZO})}}_{\text{Projected Stage I Error}} +  \underbrace{\left\| T \left[\bar{f}_{\lambda}\right] -  T f_{\ast} \right\|_{L^2(P_{ZO})}}_{\text{Projected Stage II Error}}\right) \\
    &\qquad + n^{-\frac{\frac{s_x}{d_x}+\eta_1 - \eta_0}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} (\log n)^{\frac{d_x\eta_0}{2}} .
\end{align*}

The projected stage I error can be upper bounded by \Cref{prop:projected_stage_one} as $ n > A_{\lambda,\tau}$ is satisfied for sufficiently large $n \geq 1$ proved in Eq.~\eqref{eq:n_large_than_A}. 
\begin{align*}
    \text{Projected Stage I Error} = \left\| T \left[\hat{f}_{\lambda}\right] -  T \left[\bar{f}_{\lambda}\right] \right\|_{L^2(P_{ZO})} \leq \tau n^{-\frac{\frac{s_x}{d_x}+\eta_1}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}
\end{align*}
holds with $P^{n+\tilde{n}}$-probability $\geq 1-  34e^{-\tau}$.
The projected stage II error can be upper bounded by \Cref{prop: projected upper rate}.
\begin{align*}
    \text{Projected Stage II Error} = \left\| T \left[\bar{f}_{\lambda}\right] -  T f_{\ast} \right\|_{L^2(P_{ZO})} \leq \tau n^{-\frac{\frac{s_x}{d_x}+\eta_1}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \cdot (\log n)^{\frac{d_x+d_o+1}{2}}
\end{align*}
holds with $P^n$-probability $\geq 1 - 4e^{-\tau}$. Combine the above two upper bounds, and we have
\begin{align} (\ast) = \left\|\left[\hat{f}_{\lambda}\right] - f_{\ast}\right\|_{L^2(P_{XO})} \leq \tau n^{-\frac{\frac{s_x}{d_x}+\eta_1-\eta_0}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} (\log n)^{\frac{d_x+d_o+1 + d_x\eta_0}{2}}
\end{align}
holds with $P^{n+\tilde{n}}$-probability $1 - 40e^{-\tau}$.  So the proof is concluded.

From \Cref{prop:T_hat_f_bar_f}, with $P^{n+\tilde{n}}$-probability $\geq 1 - 28e^{-\tau}$, we have
\begin{align*}
    &\left\|T\left(\left[\bar{f}_{\lambda}\right] - \left[\hat{f}_{\lambda}\right]\right)\right\|_{L^2(P_{ZO})}\\ &\lesssim \tau \lambda^{-\frac{1}{2}} \underbrace{\left(\frac{\left\|\hat{F}_{\xi}-F_*\right\|_{\mathcal{G}}}{\sqrt{n}}+\left\|F_*-[\hat{F}_{\xi}] \right\|_{L^2\left(\mathcal{Z}\times\mathcal{O}; \mathcal{H}_{X,\gamma_x}\right)} \right)}_{(\ddag)} \left(1 + \|\bar{f}_{\lambda}\|_{\mathcal{H}_{XO, \gamma_x, \gamma_0}}\right) .
\end{align*}

By \Cref{lem:f_bar_lambda_norm_bound}, we have with $P^n$-probability $\geq 1 - 2e^{-\tau}$
\begin{align*}
    \|\bar{f}_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}\lesssim \tau n^{\frac{1}{2}\frac{1 + \frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1 + (2 + \frac{d_o}{s_o})(\frac{s_x}{d_x} + \eta_1)}}.
\end{align*}

Under the probabilistic event that \Cref{prop:T_hat_f_bar_f} holds, the bounds in \Cref{prop:cme_rate} also hold, so we have
\begin{align*}
    \left\|\left[\hat{F}_\xi \right]-F_*\right\|_{L^2(\mathcal{Z}\times\mathcal{O}; \mathcal{H}_{X,\gamma_x})} \leq J \tau \tilde{n}^{-\frac{1}{2}\frac{m^{\dag}}{m^{\dag} + d^{\dag}/2 + \zeta}} , \quad \left\| \hat{F}_\xi -F_*\right\|_{\mathcal{G}} \leq J \tau \tilde{n}^{-\frac{1}{2}\frac{m^{\dag} - 1}{m^{\dag} + d^{\dag}/2 + \zeta}} ,
\end{align*}
hold for any $\zeta > 0$. $J$ is some constant independent of $\tilde{n}, n$. 
Thus under this probabilistic event, a sufficient condition so that $(\ddag)\lesssim \frac{1}{n}$ is given by
\begin{align*}
    \tilde{n} \geq (J\tau n)^{2\frac{m^{\dag}+d^{\dag}/2+\zeta}{m^{\dag}}} \vee (J^2\tau^2n)^{\frac{m^{\dag} + d^{\dag}/2 + \zeta}{m^{\dag} - 1}}.
\end{align*}
This is satisfied since $\tilde{n}$ satisfies Eq. \eqref{eq:m_sufficient_large}.
Hence,
\begin{align} \left\|\left[\hat{F}_\xi \right]-F_*\right\|_{L^2(\mathcal{Z}\times\mathcal{O}; \mathcal{H}_{X,\gamma_x})} \leq n^{-1} , \quad \left\| \hat{F}_\xi - F_*\right\|_{\mathcal{G}} \leq n^{-\frac{1}{2}} .
\end{align}

By the union bound, we have that with $P^{n+\tilde{n}}$-probability $\geq 1 - 30 e^{-\tau}$, the following bound holds
\begin{align*}
    \left\|T\left(\left[\bar{f}_{\lambda}\right] - \left[\hat{f}_{\lambda}\right]\right)\right\|_{L^2(P_{ZO})} \lesssim \tau n^{-\frac{\frac{s_x}{d_x}+\eta_1}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}.
\end{align*}
Hence the proof is concluded.

We find
\begin{align*}
    &\left\|T [\hat{f}_{\lambda}] - T [\bar{f}_{\lambda}] \right\|_{L^2(P_{ZO})} = \left\|[\hat{h}_{\lambda}] - [\bar{h}_{\lambda}] \right\|_{L^2(P_{ZO})} \leq \left\|C_{FO}^{\frac{1}{2}}\left(\hat{h}_{\lambda} - \bar{h}_{\lambda}\right)\right\|_{\mathcal{H}_{FO}} .
\end{align*}
The last step follows from Lemma 12 of \cite{fischer2020sobolev}.

We can proceed by plugging in the closed form expressions from Eq.~\eqref{eq:closed_form_h_lambdas} to have
\begin{small}
\begin{align*}
   &\left\|C_{FO}^{\frac{1}{2}}\left(\hat{h}_{\lambda} - \bar{h}_{\lambda}\right)\right\|_{\mathcal{H}_{FO}}\\ = & \left\|C_{FO}^{\frac{1}{2}}\left(\left(\hat{C}_{\hat{F}O} + \lambda\right)^{-1}\frac{1}{n}\boldsymbol{\Phi}_{\hat{F}O}^{\ast}\mathbf Y - \left(\hat{C}_{FO} + \lambda\right)^{-1}\frac{1}{n}\boldsymbol{\Phi}_{FO}^{\ast}\mathbf Y\right)\right\|_{\mathcal{H}_{FO}}\\
    \leq & \left\|C_{FO}^{\frac{1}{2}}(C_{FO} + \lambda)^{-\frac{1}{2}}\right\|\cdot \left\|(C_{FO} + \lambda)^{\frac{1}{2}}\left(\left(\hat{C}_{\hat{F}O} + \lambda\right)^{-1}\frac{1}{n}\boldsymbol{\Phi}_{\hat{F}O}^{\ast}\mathbf Y - \left(\hat{C}_{FO} + \lambda\right)^{-1}\frac{1}{n}\boldsymbol{\Phi}_{FO}^{\ast}\mathbf Y\right)\right\|_{\mathcal{H}_{FO}}\\
    \leq & \left\|(C_{FO} + \lambda)^{\frac{1}{2}}\left(\left(\hat{C}_{\hat{F}O} + \lambda\right)^{-1}\frac{1}{n}\boldsymbol{\Phi}_{\hat{F}O}^{\ast}\mathbf Y - \left(\hat{C}_{FO} + \lambda\right)^{-1}\frac{1}{n}\boldsymbol{\Phi}_{FO}^{\ast}\mathbf Y\right)\right\|_{\mathcal{H}_{FO}}\\
    \leq & S_{-1} + S_{0},
\end{align*}
\end{small}
where we define
\begin{align*}
    S_{-1} &:= \left\|(C_{FO} + \lambda)^{\frac{1}{2}}\left(\hat{C}_{\hat{F}O} + \lambda\right)^{-1} \frac{1}{n}\left(\boldsymbol{\Phi}_{\hat{F}O} - \boldsymbol{\Phi}_{FO}\right)^{\ast}\mathbf Y\right\|_{\mathcal{H}_{FO}}\\
    S_0 &= \left\|(C_{FO} + \lambda)^{\frac{1}{2}}\left(\hat{C}_{\hat{F}O} + \lambda\right)^{-1}\left(\hat{C}_{FO} - \hat{C}_{\hat{F}O}\right) \left(\hat{C}_{FO} + \lambda\right)^{-1}\frac{1}{n}\boldsymbol{\Phi}_{FO}^{\ast}\mathbf Y\right\|_{\mathcal{H}_{FO}}
\end{align*}

We bound $S_{-1}$ with $P^{n+\tilde{n}}$-high probability by \Cref{lem:thm11_meunier} and $S_{0}$ in $P^{n+\tilde{n}}$-high probability by \Cref{lem:thm12_meunier}. We thus have, with $P^{n+\tilde{n}}$-probability $\geq 1 - 28e^{-\tau}$, the following bound
\begin{align*}
    &\quad \left\|C_{FO}^{\frac{1}{2}}\left(\hat{h}_{\lambda} - \bar{h}_{\lambda}\right)\right\|_{\mathcal{H}_{FO}} \\
    &\leq c \tau\sqrt{n}\left(\frac{\left\| \hat{F}_{\xi} -F_\ast \right\|_{\mathcal{G}}}{\sqrt{n}} + \left\| \left[\hat{F}_\xi -F_*\right] \right\|_{L^2\left(\mathcal{Z}\times\mathcal{O}; \mathcal{H}_{X,\gamma_x}\right)}\right)\left(\|\bar{h}_\lambda\|_{\mathcal{H}_{FO}} + 1\right).
\end{align*}
$\|\bar{h}_\lambda\|_{\mathcal{H}_{FO}} = \|\bar{f}_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}$ since $V$ is a metric surjection.

\underline{\textit{Verification of (EVD)}}
Let $\phi_{Z}$ (resp. $\phi_{O}$) denote the feature map of $\mathcal{H}_{Z}$ (resp. $\mathcal{H}_{O}$). Define $C_{ZO}:\mathcal{H}_Z \otimes \mathcal{H}_O \to \mathcal{H}_Z \otimes \mathcal{H}_O$ as the covariance operator.
\begin{align*}
    C_{ZO} = \iint_{\mathcal{Z}\times\mathcal{O}} (\phi_Z(\mathbf z) \otimes \phi_O(\mathbf o)) \otimes (\phi_Z(\mathbf z) \otimes \phi_O(\mathbf o)) p_{ZO}(\mathbf z, \mathbf o) \;\mathrm{d}\mathbf z \;\mathrm{d}\mathbf o .
\end{align*}
We also define another two auxiliary covariance operators $\bar{C}_Z:\mathcal{H}_Z\to \mathcal{H}_Z$ and $\bar{C}_O:\mathcal{H}_O\to \mathcal{H}_O$.
\begin{align*}
    \bar{C}_Z = \int_{\mathcal{Z}} \phi_Z(\mathbf z) \otimes \phi_Z(\mathbf z) p_
    {Z}(\mathbf z)\;\mathrm{d}\mathbf z, \quad \bar{C}_O = \int_{\mathcal{O}} \phi_O(\mathbf o) \otimes \phi_O(\mathbf o)p_O(\mathbf o)\; \mathrm{d}\mathbf o .
\end{align*}
Since $k_Z$ and $k_O$ are bounded, $C_{ZO}, \bar{C}_Z, \bar{C}_O$ are all self-adjoint compact operators. 
From \cite{edmunds1996function} and \cite{fischer2020sobolev}[Section 4], we have $\lambda_i(\bar{C}_Z) \asymp i^{-2 t_z/d_z}$ and $\lambda_i(\bar{C}_O) \asymp i^{-2 t_o/d_o}$. 
We know from Assumption \ref{assn: technical} that $P_{ZO}$ is equivalent to the Lebesgue measure, so by Jensen's inequality, we have $C_{ZO} \leq \bar{C}_Z \otimes \bar{C}_O$, where $\otimes$ here denotes an operator tensor product. Hence, from Lemma 17 of \cite{meunier2024nonparametricinstrumentalregressionkernel} we have $\lambda_i(C_{ZO}) \leq \lambda_i(\bar{C}_Z \otimes \bar{C}_O)$. Finally, from \Cref{lem:tensor_evd} we have 
\begin{align*}
    \lambda_i(C_{ZO}) \leq \lambda_i(\bar{C}_Z \otimes \bar{C}_O) \lesssim i^{-2 t_z/d_z \wedge 2 t_o/d_o + \zeta}
\end{align*}
for any $\zeta > 0$.
Therefore, we have proved that (EVD) hold with $1/p = 2 t_z/d_z \wedge 2 t_o/d_o - \zeta$.
Hence, $p = d^{\dag}/2 + \zeta$ for any $\zeta > 0$.

Now we use Case 2 in Theorem 3 of \cite{JMLR:v25:23-1663} to obtain the following result: if we take $\xi = \tilde{n}^{-\frac{1}{m^{\dag} + d^{\dag}/2 + \zeta}}$, then for any $0\leq \gamma < m^{\dag}$, the following bound on the $\gamma$-norm
\begin{align*}
    \left\|\left[\hat{F}_\xi -F_*\right]\right\|_{\gamma}^2 \leq \tau^2 \tilde{n}^{-\frac{m^{\dag} - \gamma}{m^{\dag} + d^{\dag}/2 + \zeta}} .
\end{align*}
holds with $P^{\tilde{n}}$-probability at least $1 - 4e^{-\tau}$.
Therefore, noting that $m^{\dag}> 1$, by taking $\gamma=0$ and $\gamma=1$, we obtain with  $P^{\tilde{n}}$-probability at least $1 - 4e^{-\tau}$, 
\begin{align*}
    \left\|\left[\hat{F}_\xi -F_*\right]\right\|_{L^2(\mathcal{Z}\times\mathcal{O}; \mathcal{H}_{X,\gamma_x})} \leq \tau \tilde{n}^{-\frac{1}{2}\frac{m^{\dag}}{m^{\dag} + d^{\dag}/2 + \zeta}} , \quad \left\|\hat{F}_\xi -F_*\right\|_{\mathcal{G}} \leq \tau \tilde{n}^{-\frac{1}{2}\frac{m^{\dag} - 1}{m^{\dag} + d^{\dag}/2 + \zeta}} .
\end{align*}

Notice that, by definition of $F_{\ast}$, 
\begin{align*}
    \|F_{\ast}\|_{MW^{m_z, m_o}_2(\mathcal{Z}\times\mathcal{O};\mathcal{H}_{X,\gamma_x})} &= \left\|\int_{\mathcal{X}} \phi_{\gamma_x}(\mathbf x)p(\mathbf x|\cdot, \cdot)\;\mathrm{d} \mathbf x \right\|_{MW^{m_z, m_o}_2(\mathcal{Z}\times\mathcal{O};\mathcal{H}_{X,\gamma_x})} \\
    &\leq \int_{\mathcal{X}} \left\|\phi_{\gamma_x}(\mathbf x)p(\mathbf x|\cdot,\cdot )\right\|_{MW^{m_z, m_o}_2(\mathcal{Z}\times\mathcal{O};\mathcal{H}_{X,\gamma_x})}\;\mathrm{d} \mathbf x .
\end{align*}
In the last inequality above, we use \cite{Hytönen2016AnalysisBanachSpaces}[Proposition 1.2.11].

Firstly, by \citet[Eq. (2.14)]{vershynin2018high}, $P(|\upsilon|\geq t) \leq 2\exp(-\frac{ct^2}{\sigma^2})$ for some universal constant $c$. 
Define $\upsilon_i=y_i - (Tf_{\ast})(\mathbf z_i, \mathbf o_i)$ for stage II samples $\{\mathbf z_i, \mathbf o_i, y_i\}_{i=1}^n$. 
Hence
\begin{align*}
    &P^{n}\left( \{ \mathbf z_i, \mathbf o_i, y_i\}_{i=1}^n \in (\mathcal{Z} \times \mathcal{O} \times Y)^n : \max_i |\upsilon_i|\leq t\}\right)\\
    \geq & 1 - \sum_{i=1}^{n}P(|\upsilon_i|\geq t)\\
    \geq & 1 - 2\exp\left(\ln n - \frac{ct^2}{\sigma^2}\right).
\end{align*}
Hence, with $P^{n}$-probability $\geq 1 - 2\exp(-\hat{\rho})$, we have
\begin{align*}
    \max_{1\leq i\leq n}|\upsilon_i|\leq \sigma\sqrt{\frac{\ln n + \hat{\rho}}{c}}.
\end{align*}
By \Cref{ass:f_ast}, we have $\|Tf_{\ast}\|_{\infty}\leq \|f_{\ast}\|_{\infty}\leq 1$. For $n\geq 1$, we define
\begin{align*}
    M_n = 1 + \sigma\sqrt{\frac{\ln n + \hat{\rho}}{c}}.
\end{align*}
Hence $y_i \in [-M_n, M_n]$ for all $1\leq i\leq n$ with $P^n$-probability $\geq 1 - 2\exp(-\hat{\rho})$.

We are about to show that $(\forall n\geq 1) (\exists p\in (0,1))(\exists a\geq B = 4M_n^2)$ such that 
\begin{align} (\forall i\geq 1)\; \mathbb{E}_{D_{ZO}\sim P_{ZO}^{n}}e_i(\mathrm{id}:\mathcal{H}_{FO}\to L^2(D_{ZO}))\leq ai^{-\frac{1}{2p}}.
\end{align}
To this end, we invoke \citet[Corollary 7.31]{steinwart2008support}, \Cref{cor:entropy_bounded_obscov} and \Cref{lem:reduced_rkhs_entropy}. We conclude that, there exists a constant $c_p>0$ only depending on $p$, such that $(\forall i\geq 1) (\forall n\geq 1)$, we have
\begin{align*}
    &\mathbb{E}_{D_{ZO}\sim P^n_{ZO}}e_i(\mathrm{id}:\mathcal{H}_{FO}\hookrightarrow L^2(D_{ZO}))\\
    \leq & c_p(3C)^{\frac{1}{2p}}\left(\frac{d_x+d_o+1}{2ep}\right)^{\frac{d_x+d_o+1}{2p}}\left(\gamma_x^{d_x}\gamma_o^{d_o}\right)^{-\frac{1}{2p}}(\min\{i,n\})^{\frac{1}{2p}}i^{-\frac{1}{p}}\\
    \leq & c_p(3C)^{\frac{1}{2p}}\left(\frac{d_x+d_o+1}{2ep}\right)^{\frac{d_x+d_o+1}{2p}}\left(\gamma_x^{d_x}\gamma_o^{d_o}\right)^{-\frac{1}{2p}}i^{-\frac{1}{2p}}.
\end{align*}
We define a new constant $\tilde{c}_{p}:= c_p(3C)^{\frac{1}{2p}}\left(\frac{d_x+d_o+1}{2ep}\right)^{\frac{d_x+d_o+1}{2p}}$. Since for all $n\geq 1$, $\left(\gamma_x^{d_x}\gamma_o^{d_o}\right)^{-\frac{1}{2p}}\geq 1$, we set 
\begin{align*}
    a = \max\{4M_n^2, \tilde{c}_{p}\}\left(\gamma_x^{d_x}\gamma_o^{d_o}\right)^{-\frac{1}{2p}}
\end{align*}
in Eq. \eqref{eq:f_bar_lambda_hnorm_rts}, which satisfies $a \geq B = 4M_n^2$ for all $n\geq1$.

We thus apply \citet[Theorem 7.23]{steinwart2008support} restricted to the probabilistic event where $y_i\in [-2M_n, 2M_n]$ for all $1\leq i\leq n$. 
We find, with $P^{n}$-probability $\geq 1 - 5\exp(-\hat{\rho})$, 
\begin{align*}
    &\lambda \|\bar{f}_{\lambda}\|^2_{\mathcal{H}_{XO}}\leq 9\left(\lambda \|f_0\|^2_{\mathcal{H}_{XO}} + \|T(f_0 - f_{\ast})\|^2_{L^2(P_{ZO})}\right) \\ & + K\left(\frac{\max\{4M_n^2, \tilde{c}_{p}\}^{2p}\gamma_x^{-d_x}\gamma_o^{-d_o}}{\lambda^p n}\right) + \frac{216M_n^2 \hat{\rho}}{n} + \frac{15B_0\hat{\rho}}{n}
\end{align*}
where $K\geq 1$ is a constant depending on $p, M_n$, $f_0\in \mathcal{H}_{\gamma_x,\gamma_o}$. $B_0\geq B$ is a constant that satisfies
\begin{align*}
    \|L\circ (Tf_{0})\|_{\infty} &:= \sup_{(\mathbf z,\mathbf o,y)\in \mathcal{Z}\times \mathcal{O}\times [-2M_n, 2M_n]}(y - (Tf_0)(\mathbf z,\mathbf o))^2 \leq B_0,
\end{align*}
By checking the dependence of $K$ on $p, M_n$ in the proof of \citet[Theorem 7.23]{steinwart2008support}, we find that $K\leq c(p)M_n^2$ for some constant $c(p)$ depending only on $p$.

We choose $f_0 = f_{\lambda}$, where $f_{\lambda} \in \mathcal{H}_{\gamma_x,\gamma_o}$ is defined in Eq. \eqref{eq:f_lambda}. We have, since $Y = [-2M_n, 2M_n]$, 
\begin{align*}
    \|L\circ (Tf_{\lambda})\|_{\infty} = & \sup_{(\mathbf z,\mathbf o,y)\in \mathcal{Z}\times \mathcal{O}\times [-2M_n, 2M_n]} (y - (Tf_{\lambda})(\mathbf z,\mathbf o))^2 
    \leq  (2M_n + \|Tf_{\lambda}\|_{\infty})^2 \\ \leq & (2M_n + \|f_{\lambda\|_{\infty}})^2 \leq (2M_n + \|f_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}})^2 .
\end{align*}
We choose thus 
\begin{align*}
    B_0  = (2M_n + \|f_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}})^2 \geq 4M_n^2 = B.
\end{align*}

Recall $f_{\mathrm{aux}}\in \mathcal{H}_{\gamma_x,\gamma_o}$ defined in Eq.~\eqref{eq:f_aux}. We write 
\begin{align*}
    f_{\mathrm{aux}} = f_{\ast} \ast K_{\gamma_o} - (f_{\ast} - f_{\ast , \mathrm{low}}) \ast K_{\gamma_o} + (f_{\ast} - f_{\ast, \mathrm{low}}) \ast K_{\gamma_o} \ast K_{\gamma_x}
.\end{align*}

By definition of $f_\lambda$, we have
\begin{align}
    &\quad \lambda \| f_\lambda\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|T\left(f_{\ast} - \left[f_{\lambda}\right]\right)\right\|_{L^2(P_{ZO})}^2 
    \nonumber \\
    &=\inf_{f\in \mathcal{H}_{\gamma_x,\gamma_o}}\lambda \|f\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|Tf_{\ast} - T[f]\right\|_{L^2(P_{ZO})}^2\nonumber \\
    &\leq \lambda \|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|Tf_{\ast} - T[f_{\mathrm{aux}}]\right\|_{L^2(P_{ZO})}^2 \nonumber \\
    &\leq \lambda \|f_{\mathrm{aux}} \|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|Tf_{\ast} - T \left(f_{\ast} \ast K_{\gamma_o} \right)\right\|_{L^2(P_{ZO})}^2 \nonumber \\
    &+\left\| T\left((f_{\ast} - f_{\ast , \mathrm{low}}) \ast K_{\gamma_o} - (f_{\ast} - f_{\ast, \mathrm{low}}) \ast K_{\gamma_o} \ast K_{\gamma_x}\right) \right\|_{L^2(P_{ZO})}^2. \end{align}
For the first term, we know from Eq.~\eqref{eq:f_aux_norm} and \Cref{ass:f_ast} in the main text that 
\begin{align*}
    \lambda\|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 \leq n^{-1} \cdot 2 n^{\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{L^2(\mathbb{R}^{d_x+d_o})} \leq 2 n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align*}

For the second term, we have
\begin{align*}
    \left\|Tf_{\ast} - T \left(f_{\ast} \ast K_{\gamma_o} \right)\right\|_{L^2(P_{ZO})}^2 &\leq \left\|f_{\ast} - f_{\ast} \ast K_{\gamma_o} \right\|_{L^2(P_{XO})}^2 \\
    &\lesssim \left\|f_{\ast} - f_{\ast} \ast K_{\gamma_o} \right\|_{L^2(\mathcal{X}\times\mathcal{O})}^2 \\
    &\lesssim |f_{\ast}|^2_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})} \cdot \max\{0, \gamma_o^{2s_o}\}\\
    &= |f_{\ast}|^2_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})}  n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}.
\end{align*}
The first inequality above holds because $T$ is a bounded operator;
the second inequality holds by Assumption \ref{assn: technical} that $P_{XO}$ admits a bounded density. 
The second last inequality above holds by using \Cref{lem:hang_prop_3} for $\boldsymbol{\gamma} = (\underbrace{0,\dots, 0}_{d_x},\underbrace{\gamma_o,\dots,\gamma_o}_{d_o})$.

In addition to that, from Eq.~\eqref{eq:proj_approx_error}, we also have
\begin{align} \left\|Tf_{\ast} - T[f_{\mathrm{aux}}]\right\|_{L^2(P_{ZO})} \leq C n^{-\frac{\frac{s_x}{d_x}+\eta_1}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align}
Also, if we follow the same derivations as above, we obtain
\begin{align} \left\|f_{\ast} - [f_{\mathrm{aux}}] \right\|_{L^2(P_{XO})} \leq C n^{-\frac{\frac{s_x}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align}

Recall the definition of $\bar{h}_{\lambda}$ defined in Eq.~\eqref{eq:hat_bhl_bvfl} and $h_\lambda$ defined in Eq.~\eqref{eq:bhl_bvfl}.
\begin{align*}
    \bar{h}_{\lambda} &= arg\,min_{h\in \mathcal{H}_{FO}}\lambda \|h\|_{\mathcal{H}_{FO}}^2 + \frac{1}{n}\sum_{i=1}^{n}(h(\mathbf z_i,\mathbf o_i) - y_i)^2 . \\
    h_{\lambda} &= arg\,min_{h\in\mathcal{H}_{FO}}\lambda \|h\|^2_{\mathcal{H}_{FO}} + \|h_{\ast} - h\|^2_{L^2(P_{ZO})}.
\end{align*} 
Recall that we have proved that $\|T([\bar{f}_{\lambda}] - [f_{\lambda}])\|_{L^2(P_{ZO})} = \|[\bar{h}_{\lambda}] - [h_{\lambda}] \|_{L^2(P_{ZO})}$ in Eq.~\eqref{eq:error_translate}, so the proof of \Cref{prop: projected_est_error} is translated to the estimation error of a standard kernel ridge regression with hypothesis space $\mathcal{H}_{FO}$ and the target function $h_\ast := T f_\ast \in L^2(P_{ZO})$. Next, we are going to apply existing results, mainly Theorem 16 of \cite{fischer2020sobolev}, to our setting.

Next, we control the auxiliary quantities in \cite{fischer2020sobolev}[Theorem 16]. Recall $m_z,m_o$ as defined in Eq. \eqref{def:m_z,m_o}. By definition, they satisfy
\begin{align*}
    \frac{d_o}{2m_o}<\frac{1 + 2\left(\frac{s_x}{d_x}+\eta_1\right)}{1+2\left(\frac{s_x}{d_x}+\eta_1\right) + \frac{d_o}{s_o}\left(\frac{s_x}{d_x}+\eta_1\right)}<1 , \quad \frac{d_z}{2m_z}\leq \frac{d_o}{2m_o} < 1 .
\end{align*}
Rearranging, we deduce that
\begin{align*}
    \frac{d_o}{2m_o} &< \left( 2m_o\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)} + 1\right)^{-1}\\ \frac{d_o}{2m_o} &< \frac{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}{1+2(\frac{s_x}{d_x}+\eta_1)+\frac{2m_o+d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}.
\end{align*}
Hence there exists $\theta\in (0,1)$ such that the following inequalities hold simultaneously
\begin{align} \begin{aligned}
    \frac{d_o}{2m_o\theta} < 1, \quad \frac{d_z}{2m_z\theta} < 1 \\
    \theta \leq \frac{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}{1+2(\frac{s_x}{d_x}+\eta_1)+\frac{2m_o+d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}\\
    \theta\left( 2m_o\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)} + 1\right) < 1
\end{aligned}
\end{align}
Next, we define 
\begin{align} \begin{aligned}
    g_{\lambda}&:= \log\left(2e\mathcal{N}_{FO}(\lambda)\frac{\|C_{FO}\|+\lambda}{\|C_{FO}\|}\right)\\
    A_{\lambda,\tau}&:= 8\left\|k^{\theta}_{FO}\right\|_{\infty}^2\tau g_{\lambda}\lambda^{-\theta}\\
    L_{\lambda}&:=\max\left\{L, \left\|h_{\ast} - [h_{\lambda}]\right\|_{L^{\infty}(P_{ZO})}\right\}
\end{aligned}
\end{align}

\textit{Controlling $g_{\lambda}$ and $A_{\lambda,\tau}$:  } 
From \Cref{prop:eff_dim}, we know that
\begin{align*}
    \mathcal{N}_{FO}(\lambda) \lesssim (\log n)^{d_x+d_o+1} \left(\gamma_x^{d_x}\gamma_o^{d_o}\right)^{-1} = (\log n)^{d_x+d_o+1} n^{\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align*}
From \Cref{lem: C_f_op_norm_lower_bound}, we know that
\begin{align*}
    \|C_{FO}\| \geq a_f^{-1}\left(\frac{\sqrt{\pi}}{4}\right)^{\frac{d_x+d_o}{2}} n^{-\frac{1}{2}\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align*}
Therefore, since $\lambda \asymp n^{-1}$, we have
\begin{align*}
    g_{\lambda } &= \log\left(2e\mathcal{N}_{FO}(\lambda) \left(1 + \lambda \|C_{FO}\|^{-1} \right) \right) \\
    &\lesssim \log\left((\log n)^{d_x+d_o+1} n^{\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \left(1 + n^{-1} \cdot n^{\frac{1}{2}\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)} }\right)\right)\\
    &\leq \log\left(2(\log n)^{d_x+d_o+1} n^{\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \right)\\
    &= (d_x + d_o + 1)\log(\log n) + \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)} \log(n)\\
    &\leq 2\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}\log(n).
\end{align*}
The last step holds because $\log(n)$ dominates a constant term and $\log(\log n)$ for sufficiently large $n$. Since $\frac{d_o}{2m_o\theta}<1, \frac{d_z}{2m_z\theta}<1$, by \Cref{prop:emb_main}, we have
\begin{align}
    \left\|k_{FO}^{\theta}\right\|_{\infty} \lesssim \rho^{\theta}\gamma_o^{-\theta m_o} .
\end{align}
Therefore, 
\begin{align} A_{\lambda,\tau} &\lesssim \left\|k_{FO}^{\theta}\right\|_{\infty}^2\tau \log(n)n^{\theta} \lesssim \gamma_o^{-2m_o\theta}\tau \log(n)n^{\theta} = \tau \log(n) n^{\theta\left( 2m_o\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)} + 1\right)}.
\end{align}
Since $\theta ( 2m_o\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)} + 1) < 1$ from Eq.~\eqref{eq:theta_cond}, $n>  A_{\lambda,\tau}$ holds for sufficiently large $n \geq 1$.

\textit{Controlling $L_{\lambda}$:  } 
By Eq. \eqref{eq:lambda_f_lambda_T_L2}, we have
\begin{align*}
    \lambda \|f_{\lambda}\|^2_{\mathcal{H}_{\gamma_x,\gamma_o}} \leq n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})}^2 .
\end{align*}
Thus 
\begin{align} \|f_{\lambda}\|^2_{\mathcal{H}_{\gamma_x,\gamma_o}} \leq n^{\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{B^{s_x,s_o}_{2,q} (\mathbb{R}^{d_x+d_o})}^2 .
\end{align}
Thus we have
\begin{align}
    L_{\lambda} &= \max\left\{2C\sigma, \|T(f_{\ast} - [f_{\lambda}])\|_{L^{\infty}(\mathcal{Z}\times \mathcal{O})}\right\}\nonumber\\
    &\leq \max\left\{2C\sigma, \|f_{\ast} - [f_{\lambda}]\|_{L^{\infty}(\mathcal{X}\times \mathcal{O})}\right\}\nonumber\\
    &\leq  \max\left\{2C\sigma, \|f_{\ast}\|_{L^{\infty}(\mathcal{X}\times \mathcal{O})} + \|[f_{\lambda}]\|_{L^{\infty}(\mathcal{X}\times \mathcal{O})}\right\}\nonumber\\
    &\stackrel{(i)}{\leq} \max\left\{2C\sigma, \|f_{\ast}\|_{L^{\infty}(\mathcal{X}\times \mathcal{O})} + \|f_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}\right\}\nonumber\\
    &\stackrel{(ii)}{\leq} \max\left\{2C\sigma, \|f_{\ast}\|_{L^{\infty}(\mathcal{X}\times \mathcal{O})} + n^{\frac{1}{2}\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{B^{s_x,s_o}_{2,q} (\mathbb{R}^{d_x+d_o})} \right\}\nonumber\\
    &\stackrel{(iii)}{\leq} 2 n^{\frac{1}{2}\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{B^{s_x,s_o}_{2,q} (\mathbb{R}^{d_x+d_o})} ,
\end{align}
where $(i)$ holds by the reproducing property, $(ii)$ holds by Eq. \eqref{eq:f_lambda_hnorm_bound}, and $(iii)$ holds for sufficiently large $n$.

\textit{Bounding $(\ast)$:  } Now we are ready to apply \cite{fischer2020sobolev}[Theorem 16] to upper bound $(\ast)$. 
By \cite{fischer2020sobolev}[Theorem 16], with $P^n$-probability $\geq 1 - 4e^{-\tau}$, for $n\geq A_{\lambda,\tau}$,
\begin{small}
\begin{align*}
    (\ast) &= \left\|C_{FO}^{\frac{1}{2}}\left(\bar{h}_{\lambda} - h_{\lambda}\right)\right\|_{\mathcal{H}_{FO}}^2 
    \\ \leq &\frac{576\tau^2}{n} \left(\sigma^2\mathcal{N}_{FO}(\lambda) + \left\|k^{\theta}_{FO}\right\|_{\infty}^2\frac{\left\|h_{\ast} - [h_{\lambda}]\right\|_{L^2(P_{ZO})}^2}{\lambda^{\theta}} + 2\left\|k^{\theta}_{FO}\right\|_{\infty}^2\frac{L_{\lambda}^2}{n\lambda^{\theta}} \right) \\
    \stackrel{(a)}{\lesssim} &\frac{\tau^2}{n} \left((\log n)^{d_x+d_o+1} n^{\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} + \left\|k^{\theta}_{FO}\right\|_{\infty}^2n^{\theta}\left(\left\|h_{\ast} - [h_{\lambda}]\right\|_{L^2(P_{ZO})}^2 + \frac{L_{\lambda}^2}{n}\right)\right)\\
    \stackrel{(b)}{\lesssim} & \tau^2\left(n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} (\log n)^{d_x+d_o+1} + \gamma_o^{-2m_o\theta}  n^{\theta-1} \cdot n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}\right)\\
    \stackrel{(c)}{\lesssim} & \tau^2\left(n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} (\log n)^{d_x+d_o+1} + n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \right)\\
    \lesssim & \tau^2 n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} (\log n)^{d_x+d_o+1}.
\end{align*}
\end{small}
We use Proposition~\ref{prop:eff_dim} to upper bound $\mathcal{N}_{FO}(\lambda)$ in $(a)$,
we use Eq. \eqref{eq:l_lambda_bound} to upper bound $L_\lambda$, Eq. \eqref{eq: kfo_bound} to upper bound $\|k^{\theta}_{FO}\|_{\infty}$ and \Cref{prop: approx_error} to upper bound $ \|h_{\ast} - [h_{\lambda}]\|_{L^2(P_{ZO})} = \|T f_{\ast} - T[f_{\lambda}]\|_{L^2(P_{ZO}}$ in $(b)$, and we use the following fact in $(c)$: by Eq.~\eqref{eq:theta_cond}, we have
\begin{align*}
    &\theta \leq \frac{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}{1+2(\frac{s_x}{d_x}+\eta_1)+\frac{2m_o+d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)} \\
    \iff & n^{\frac{\frac{2m_o \theta}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} n^{\theta-1} \leq 1\\
    \iff & \gamma_o^{-2m_o\theta}n^{\theta-1} \leq 1. 
\end{align*}
The proof is concluded.

We adapt the proof of \citet{meunier2024nonparametricinstrumentalregressionkernel}[Theorem 12]. 
\begin{align*}
\begin{aligned}
S_0
= & \left\|\left(C_{FO}+\lambda \right)^{1 / 2}\left(\hat{C}_{\hat{F}O}+\lambda \right)^{-1}\left(\hat{C}_{\hat{F}O}-\hat{C}_{FO}\right)\left(\hat{C}_{FO}+\lambda \right)^{-1} \frac{1}{n} \boldsymbol{\Phi}_{FO}^\ast \boldsymbol{Y} \right\|_{\mathcal{H}_{FO}} \\
\leq & \lambda^{-1 / 2} \underbrace{\left\|\left(C_{FO}+\lambda \right)^{1 / 2}\left(\hat{C}_{FO}+\lambda \right)^{-1 / 2}\right\|}_{(A)} \\
&\cdot \underbrace{\left\|\left(\hat{C}_{FO}+\lambda \right)^{1 / 2}\left(\hat{C}_{\hat{F} O}+\lambda \right)^{-1 / 2}\right\|}_{(B)} \cdot \underbrace{\left\|\hat{C}_{\hat{F}O}-\hat{C}_{FO}\right\|}_{(C)} \cdot \left\|\bar{h}_\lambda\right\|_{\mathcal{H}_{FO}}
\end{aligned}
\end{align*}
\underline{Upper bound for term $(A)$}. Notice that all assumptions from \citet[Lemma 17]{fischer2020sobolev} have been checked already in the analysis of projected estimation error in \Cref{sec:esti_main}.
Since $n\geq A_{\lambda,\tau}$ with $A_{\lambda,\tau}$ defined in Eq. \eqref{eq:FS_thm_16_const}, with $P^n$-probability $\geq 1 - 2e^{-\tau}$,
\begin{align*}
    \left\|\left(C_{FO} +\lambda\right)^{-1 / 2}\left(C_{FO} -\hat{C}_{FO}\right) \left(C_{FO}+\lambda\right)^{-1 / 2} \right\| &\leq \frac{4\left\|k^{\theta}_{FO}\right\|_{\infty}^2 \tau g_\lambda}{3 n \lambda^\theta}+\sqrt{\frac{2\left\|k^{\theta}_{FO}\right\|_{\infty}^2 \tau g_\lambda}{n \lambda^\theta}} \\
    &\leq \frac{2}{3}.
\end{align*}
By \citet[Proposition 7]{rudi2015less}, we have
\begin{align*}
    (A) \leq \left(1 - \left\|\left(C_{FO} +\lambda\right)^{-1 / 2}\left(C_{FO} -\hat{C}_{FO}\right) \left(C_{FO}+\lambda\right)^{-1 / 2} \right\|\right)^{-\frac{1}{2}} \leq (1/3)^{-\frac{1}{2}} \leq 2.
\end{align*}

\underline{Upper bound for term $(B)$}. By \citet[Proposition 7]{rudi2015less}, we have $
(B)\leq (1-t)^{-\frac{1}{2}}$, where
\begin{small}
\begin{align*}
    t&:=\left\|\left(\hat{C}_{FO} + \lambda\right)^{-\frac{1}{2}}\left(\hat{C}_{FO} - \hat{C}_{\hat{F}O}\right)\left(\hat{C}_{FO} + \lambda \right)^{-\frac{1}{2}}\right\| \leq \lambda^{-1}\left\|\hat{C}_{FO} - \hat{C}_{\hat{F}O}\right\| = n \cdot (C) \leq \frac{1}{6}, 
\end{align*}
\end{small}
from where we have $(B)\leq \frac{6}{5}$.

Notice that
\begin{align*}
\begin{aligned}
&\quad K_{\boldsymbol{\gamma}} * f(\mathbf x) =\int_{\mathbb{R}^d} \sum_{j=1}^r\binom{r}{j}(-1)^{1-j} \frac{1}{j^d}\left(\frac{2}{\pi}\right)^{\frac{d}{2}} \left( \prod_{i=1}^{d} \frac{1}{\gamma_i} \right) \exp\left( -2 \sum_{i=1}^d \frac{(x_i - t_i)^2}{j^2 \gamma_i^2} \right) f(\boldsymbol{t}) \;\mathrm{d}\boldsymbol{t} \\
& =\sum_{j=1}^r\binom{r}{j}(-1)^{1-j} \frac{1}{j^d} \left(\frac{2}{\pi}\right)^{\frac{d}{2}} \left( \prod_{i=1}^{d} \frac{1}{\gamma_i} \right) \int_{\mathbb{R}^d} \exp\left( -2 \sum_{i=1}^d \frac{(x_i - t_i)^2}{j^2 \gamma_i^2} \right) f(\boldsymbol{t}) \;\mathrm{d}\boldsymbol{t} \\
& =\sum_{j=1}^r\binom{r}{j}(-1)^{1-j} \frac{1}{j^d}\left(\frac{2}{\pi}\right)^{\frac{d}{2}} \left( \prod_{i=1}^{d} \frac{1}{\gamma_i} \right) \int_{\mathbb{R}^d} \exp\left( -2 \sum_{i=1}^d \frac{h_i^2}{\gamma_i^2} \right)  f(\mathbf x + j \boldsymbol{h}) j^d \;\mathrm{d}\boldsymbol{h} \\
& =\sum_{j=1}^r\binom{r}{j}(-1)^{1-j} \left(\frac{2}{\pi}\right)^{\frac{d}{2}} \int_{\mathbb{R}^d} \exp\left( -2 \| \boldsymbol{h}\|^2 \right)  f(\mathbf x + j \boldsymbol{h} \odot \boldsymbol{\gamma}) \;\mathrm{d}\boldsymbol{h} \\
& = \int_{\mathbb{R}^d}\left(\frac{2}{\pi}\right)^{\frac{d}{2}} \exp\left( -2 \| \boldsymbol{h}\|^2 \right) \left(\sum_{j=1}^r \binom{r}{j}(-1)^{1-j} f( \mathbf{x} + j \boldsymbol{h} \odot \boldsymbol{\gamma} )\right) \;\mathrm{d}\boldsymbol{h} .
\end{aligned}
\end{align*}

Then, from Cauchy-Schwarz inequality, we have
\begin{small}
\begin{align} &\leq  \int_{\mathcal{X}} \left( \int_{\mathbb{R}^d} \left(\frac{2}{\pi}\right)^{\frac{d}{2}} \exp\left( -2 \| \boldsymbol{h}\|^2 \right) \;\mathrm{d}\boldsymbol{h}\right) \left( \int_{\mathbb{R}^d} \left(\frac{2}{\pi}\right)^{\frac{d}{2}} \exp\left( -2 \| \boldsymbol{h}\|^2 \right) \left| \Delta_{\boldsymbol{h} \odot \boldsymbol{\gamma}}^r f(\mathbf x) \right|^2 \;\mathrm{d}\boldsymbol{h} \right) \;\mathrm{d}\mathbf x \nonumber \\
    &= \int_{\mathcal{X}} \int_{\mathbb{R}^d} \left(\frac{2}{\pi}\right)^{\frac{d}{2}} \exp\left( -2 \| \boldsymbol{h}\|^2 \right) \left| \Delta_{\boldsymbol{h} \odot \boldsymbol{\gamma}}^r f(\mathbf x) \right|^2 \;\mathrm{d}\boldsymbol{h}  \;\mathrm{d}\mathbf x \nonumber \\
    &= \int_{\mathbb{R}^d} \left(\frac{2}{\pi}\right)^{\frac{d}{2}} \exp\left( -2 \| \boldsymbol{h}\|^2 \right) \left\| \Delta_{\boldsymbol{h} \odot \boldsymbol{\gamma}}^r f \right\|_{L^2(\mathcal{X})}^2  \;\mathrm{d}\boldsymbol{h} .
\end{align}
\end{small}

Notice that
\begin{align*}
    C_0^2 := d \int_{\mathbb{R}^d} \left(\frac{2}{\pi}\right)^{\frac{d}{2}} \exp\left( -2 \| \boldsymbol{h}\|^2 \right) \left(\sum_{i=1}^d h_i^{2 s_i}\right) \;\mathrm{d}\boldsymbol{h} = d \sum_{i=1}^d \int_{\mathbb{R}} \left(\frac{2}{\pi}\right)^{\frac{1}{2}} \exp\left( -2 h_i^2 \right) h_i^{2 s_i }dh_i,
\end{align*}
which is the sum of $s_i$-th moment of a one dimensional Gaussian distribution $\mathcal{N}(0, 1/4)$ from $i=1$ to $i=d$.

Finally, we obtain
\begin{align*}
    \left\| K_{\boldsymbol{\gamma}} * f - f\right\|_{L^2(\mathcal{X})}^2 &\leq C_0^2 |f|_{B_{2,q}^{\boldsymbol{s}}(\mathcal{X})}^2 N^{-2} = C_0^2 |f|_{B_{2,q}^{\boldsymbol{s}}(\mathcal{X})}^2 \left( \max\{\gamma_1^{s_1}, \ldots, \gamma_d^{s_d}\} \right)^2 .
\end{align*}

In contrast to the notation used in the rest of the document (with the exception of \Cref{lem:l2toprojected_illp}), in this proof, we use $\mathcal{F}$ to denote the unitary Fourier operator on $L^2(\mathbb{R}^{d_x+d_o})$, we use $\mathcal{F}_x$ to denote the unitary Fourier operator on $L^2(\mathbb{R}^{d_x})$, and we use $\mathcal{F}_o$ to denote the unitary Fourier operator on $L^2(\mathbb{R}^{d_o})$. We let $\otimes: L^2(\mathbb{R}^{d_x})\times L^2(\mathbb{R}^{d_o})\to L^2(\mathbb{R}^{d_x+d_o})$ denotes the tensor product mapping, where $(f\otimes g)(\mathbf x,\mathbf o) = f(\mathbf x)g(\mathbf o)$ for all $(\mathbf x,\mathbf o)\in \mathbb{R}^{d_x+d_o}$. By considering a convergent sequence to $f_1$ in $L^1(\mathbb{R}^{d_x})\cap L^2(\mathbb{R}^{d_x})$, and similarly for $f_2$, we can show that 
\begin{align*}
    \mathcal{F}[f\otimes g] = \mathcal{F}_x[f]\otimes \mathcal{F}_o[g]
\end{align*}
for $f\in L^2(\mathbb{R}^{d_x})$ and $g\in L^2(\mathbb{R}^{d_o})$.

At the start of \Cref{sec:proof_upper}, we proved that for $f\in L^1(\mathbb{R}^{d_x+d_o})$, $f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}] \in L^2(\mathbb{R}^{d_x+d_o})$. Since $\|K_{\gamma_o}\|_{L^1(\mathbb{R}^{d_o})}= 1$ \citep[Section 4.1.2]{Giné_Nickl_2015}, we have
\begin{align*}
    \|(f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}])\ast K_{\gamma_o}\|_{L^2(\mathbb{R}^{d_x+d_o})}^2 &\stackrel{(a)}{=} \int_{\mathbb{R}^{d_x}}\|(f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}])(\mathbf x,\cdot) \ast K_{\gamma_o}\|^2_{L^2(\mathbb{R}^{d_o})}\;\mathrm{d}\mathbf x\\
    &\stackrel{(b)}{\leq} \int_{\mathbb{R}^{d_x}} \|(f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}])(\mathbf x,\cdot)\|^2_{L^2(\mathbb{R}^{d_o})} \|K_{\gamma_o}\|^2_{L^1(\mathbb{R}^{d_o})}\\
    & = \|f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]\|^2_{L^2(\mathbb{R}^{d_x+d_o})}.
\end{align*}
where in $(a)$, $(f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}])(\mathbf x,\cdot)$ is a slice function of any representative of $f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]\in L^2(\mathbb{R}^{d_x})$, and $(b)$ follows from Young's Convolution Inequality. Hence we can apply $\mathcal{F}$ to $f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]\in L^2(\mathbb{R}^{d_x+d_o})$ and we find 
\begin{align*}
    \mathcal{F}\left[\mathcal{F}_x^{-1}[\iota_{x,\gamma_x^{-1}}] \ast K_{\gamma_o} \ast f\right] = (\iota_{x,\gamma_x^{-1}}\otimes \mathcal{F}_o[K_{\gamma_o}]) \cdot \mathcal{F}[f].
\end{align*}

For $\phi(\mathbf x,\mathbf o) = \exp(- \gamma_x^{-2} \|\mathbf x\|_2^2) \cdot \exp(- \gamma_o^{-2} \|\mathbf o\|_2^2)$, its Fourier transform is 
\begin{align*}
    \mathcal{F}[\phi](\boldsymbol{\omega}_x,\boldsymbol{\omega}_o) = \pi^{d_x/2+d_o/2} \gamma_x^{d_x} \exp\left(-\frac{1}{4} \gamma_x^{2} \|\boldsymbol{\omega}_x\|_2^2\right) \cdot \gamma_o^{d_o}\exp\left(-\frac{1}{4} \gamma_o^{2} \|\boldsymbol{\omega}_o\|_2^2\right).
\end{align*}
Hence, by definition of Gaussian RKHS norm~\citep[Theorem 10.12]{wendland2004scattered}, 
\begin{align*}
    &\quad \left\| \mathcal{F}_x^{-1}[\iota_{x,\gamma_x^{-1}}]\ast K_{\gamma_o} \ast f\right\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 \\
    &= \int_{\mathbb{R}^{d_x+d_o}} \frac{\left(\iota_{x,\gamma_x^{-1}}(\boldsymbol{\omega}_x) \cdot \mathcal{F}[f](\boldsymbol{\omega}_x,\boldsymbol{\omega}_o) \cdot \mathcal{F}_o[K_{\gamma_o}](\boldsymbol{\omega}_o)\right)^2}{\pi^{d_x/2+d_o/2} \gamma_x^{d_x} \exp\left(-\frac{1}{4} \gamma_x^{2} \|\boldsymbol{\omega}_x\|_2^2\right) \cdot \gamma_o^{d_o}\exp(-\frac{1}{4} \gamma_o^{2} \|\boldsymbol{\omega}_o\|_2^2)} \;\mathrm{d}\boldsymbol{\omega}_x \;\mathrm{d}\boldsymbol{\omega}_o \\
    &\lesssim \gamma_x^{-d_x} \gamma_o^{-d_o} \int_{\mathbb{R}^{d_o}}\int_{\{\boldsymbol{\omega}_x: \|\boldsymbol{\omega}_x\|_2 \leq \gamma_x^{-1} \}} \frac{\left( \mathcal{F}[f](\boldsymbol{\omega}_x,\boldsymbol{\omega}_o) \cdot \mathcal{F}_o[K_{\gamma_o}](\boldsymbol{\omega}_o)\right)^2}{\exp\left(-\frac{1}{4} \gamma_x^{2} \|\boldsymbol{\omega}_x\|_2^2\right) \cdot \exp(-\frac{1}{4} \gamma_o^{2} \|\boldsymbol{\omega}_o\|_2^2)} \;\mathrm{d}\boldsymbol{\omega}_x \;\mathrm{d}\boldsymbol{\omega}_o \\
    &\lesssim \gamma_x^{-d_x} \gamma_o^{-d_o} \int_{\mathbb{R}^{d_x+d_o}} \exp\left(\frac{1}{4} \gamma_o^{2} \|\boldsymbol{\omega}_o\|_2^2\right)\left(\mathcal{F}[f](\boldsymbol{\omega}_x,\boldsymbol{\omega}_o) \cdot \mathcal{F}_o[K_{\gamma_o}](\boldsymbol{\omega}_o)\right)^2 \;\mathrm{d}\boldsymbol{\omega}_x \;\mathrm{d}\boldsymbol{\omega}_o .
\end{align*}

Since $K_{\gamma_o}(\mathbf o) :=  \sum_{j=1}^r\binom{r}{j}(-1)^{1-j} \frac{1}{j^{d_o}\gamma_o^{d_o}}\left(\frac{2}{\pi}\right)^{\frac{d}{2}}  \exp( -2 j^{-2} \gamma_o^{-2} \|\mathbf o\|_2^2)$, so we have 
\begin{align*}
    \mathcal{F}_o[K_{\gamma_o}](\boldsymbol{\omega}_o) = \sum_{j=1}^r\binom{r}{j}(-1)^{1-j} \exp\left(-\frac{1}{8} j^2 \gamma_o^2 \|\boldsymbol{\omega}_o\|_2^2\right) .
\end{align*}
Consequently, we have
\begin{align*}
    &\quad \left\| \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]\ast K_{\gamma_o} \ast f\right\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 \\
    &\lesssim \gamma_x^{-d_x} \gamma_o^{-d_o} \int_{\mathbb{R}^{d_x+d_o}} \frac{\left(\mathcal{F}[f](\boldsymbol{\omega}_x,\boldsymbol{\omega}_o) \cdot \sum_{j=1}^r\binom{r}{j}(-1)^{1-j} \exp(-\frac{1}{8} j^2 \gamma_o^2 \|\boldsymbol{\omega}_o\|_2^2) \right)^2}{\exp(-\frac{1}{4} \gamma_o^{2} \|\boldsymbol{\omega}_o\|_2^2)} d\boldsymbol{\omega}_x d\boldsymbol{\omega}_o \\
    &\leq \gamma_x^{-d_x} \gamma_o^{-d_o} 2^{2r} \int_{\mathbb{R}^{d_x+d_o}} \left(\mathcal{F}[f](\boldsymbol{\omega}_x,\boldsymbol{\omega}_o) \right)^2 d\boldsymbol{\omega}_x d\boldsymbol{\omega}_o \\
    &= \gamma_x^{-d_x} \gamma_o^{-d_o} 2^{2r} \| f\|_{L^2(\mathbb{R}^{d_x+d_o})}^2 .
\end{align*}
where the last equality follows by Plancherel's Theorem.

By \cite{kanagawa2018gaussianprocesseskernelmethods}[Theorem 2.4], we have
\begin{align*}
    \|f\|_{\mathcal{H}_{X,\boldsymbol{\gamma}}}^2 &= (2\pi)^{-d} \int_{\mathbb{R}^d} \frac{|\mathcal{F}[f](\boldsymbol{\omega})|^2}{\mathcal{F}[\phi_{X,\boldsymbol{\gamma}}](\boldsymbol{\omega})} d \boldsymbol{\omega} \\
    &=(2\pi)^{-d} \pi^{d/2} \int_{\mathbb{R}^d} |\mathcal{F}[f](\boldsymbol{\omega})|^2 \left(\prod_{i=1}^{d}\gamma_i\right)^{-1}\exp\left(\frac{\|\boldsymbol{\omega}\odot \boldsymbol{\gamma}\|_{2}^{2}}{4}\right) \mathrm{d}\boldsymbol{\omega}\; \\
    &= 2^{-d} \pi^{-d/2} \left(\prod_{i=1}^{d} \gamma_i\right)^{-1} \int  |\mathcal{F}[f](\boldsymbol{\omega})|^2 \exp\left(\frac{\|\boldsymbol{\omega}\odot \boldsymbol{\gamma}\|_{2}^{2}}{4}\right) \mathrm{d}\boldsymbol{\omega}
\end{align*}
whence the Lemma follows.

Define the following sets 
\begin{align*}
    I_{\mathbf x} &:= \left\{\boldsymbol{\omega}_{x}\in\mathbb{R}^{d_x}: \|\boldsymbol{\omega}_x\|_2^2 \gamma_x^{2} (\log (\gamma_x^{-\delta_x}))^{-1} \leq 1 \right\}\\ \quad I_{\mathbf o} &:= \left\{\boldsymbol{\omega}_{o}\in\mathbb{R}^{d_o}: \|\boldsymbol{\omega}_{o}\|^2_{2}\gamma_o^{2} (\log (\gamma_o^{-\delta_o}))^{-1} \leq 1\right\}\\ I &:= I_{\mathbf x} \times I_{\mathbf o}\\
