    &\stackrel{(i)}{\leq} \gamma_x^{-d_x\eta_0} (\log (\gamma_x^{-\delta_x}))^{\frac{d_x\eta_0}{2}} \|T(f\ast \mathcal{F}^{-1}(\iota))\|_{L^2(P_{ZO})} + \left\|f\ast \mathcal{F}^{-1}(\iota) - f\right\|_{L^2(P_{XO})} \nonumber\\
