    \nonumber \\
    &\lesssim \gamma_x^{-d_x\eta_0} (\log (\gamma_x^{-\delta_x}))^{\frac{d_x\eta_0}{2}} \|Tf\|_{L^2(P_{ZO})}  + \gamma_x^{-d_x\eta_0} (\log (\gamma_x^{-\delta_x}))^{\frac{d_x\eta_0}{2}} \left\|f\ast \mathcal{F}^{-1}(\iota) - f\right\|_{L^2(\mathcal{X}\times\mathcal{O})} .
