\end{align*}
where we note that the relevant Fourier transforms exist since $f\in \mathcal{H}_{\gamma_x,\gamma_o}\subset L^2(\mathbb{R}^{d_x+d_o})$. 
    \item $(ii)$ follows from a triangular inequality and a Jensen's inequality. 
\end{itemize}

$(i)$ follows from \Cref{ass:T_frequency_ill_posedness}, and for $\mathcal{F}_x,\mathcal{F}_o$ defined in the proof of \Cref{lem:mixed_convolution},
\begin{align*}
