\end{align*}
where $(a)$ holds by Plancherel's Theorem, $(b)$ holds by $\tilde{I}\subseteq I$. 
Recall that for $\mathbf{a}, \mathbf{b}\in\mathbb{R}^d$, $\mathbf{a} \odot \mathbf{b} := (a_1 b_1, \ldots, a_d b_d) \in \mathbb{R}^{d}$. For $\boldsymbol{\omega}=(\boldsymbol{\omega}_x, \boldsymbol{\omega}_o)$, we proceed from above to have,
\begin{small}
\begin{align*}
    &\leq \left(\int_{\tilde{I}^{c}} |\mathcal{F}[f](\boldsymbol{\omega})|^2 \exp\left(\frac{\|(\boldsymbol{\omega}_x \odot \boldsymbol{\gamma}_x, \boldsymbol{\omega}_o \odot \boldsymbol{\gamma}_o )\|^2_{2}}{4}\right)\exp\left(-\frac{\|(\boldsymbol{\omega}_x \odot \boldsymbol{\gamma}_x, \boldsymbol{\omega}_o \odot \boldsymbol{\gamma}_o ) \|^2_{2}}{4}\right)\;\mathrm{d}\boldsymbol{\omega}\right)^{\frac{1}{2}}\\
