        &= \gamma^2 \sqrt{\pi} \int_{0}^{\frac{1}{2\gamma}} \mathrm{erf}(y)  \;\mathrm{d} y \\
        &= \gamma^2 \sqrt{\pi} \left[\frac{\mathrm{erf}\left(\frac{1}{2\gamma}\right)}{2\gamma} + \frac{\exp\left(-\frac{1}{4\gamma^2}\right)-1}{\sqrt{\pi}}\right] . 
    \end{align*}
    where the last inequality holds by using the identity
    \begin{align*}
        \int \mathrm{erf}(x) d x = x \cdot \mathrm{erf}(x) + e^{-x^2} / \sqrt{\pi} + C.
    \end{align*}

\underline{\emph{Step One.}}
We take $\mathfrak{m}$ to be the smallest even integer such that $\mathfrak{m} > s_x \vee s_o$.
