In this step, we are going to prove that $f_{\mathbf v}\in B_{2,\infty}^{s_x,s_o}(\mathbb{R}^{d_x+d_o})$ and its Besov norm is bounded by $\epsilon_0$.
We have, $(\forall\mathbf o\in \mathcal{O})$, 
\begin{align} &\mathcal{F}[f_{\mathbf v}(\cdot,\mathbf o)](\boldsymbol{\omega}_x) = \epsilon_0 2^{-\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} \sum_{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o}\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\mathcal{F}[\Omega_{\mathfrak{K}({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}(\cdot, \mathbf o)](\boldsymbol{\omega}_x) \nonumber \\ 
    &= \epsilon_0 2^{-\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} \sum_{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o}\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}](\boldsymbol{\omega}_x) \cdot M_{\mathfrak{K},{\boldsymbol\ell}_o}(\mathbf o) \nonumber \\
    &= \epsilon_0 2^{-\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} \sum_{{\boldsymbol\ell}_x, {\boldsymbol\ell}_o} \beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} 2^{-\mathfrak{K}\frac{\underline{s}d_x}{s_x}}\mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}] \left(2^{-\mathfrak{K}\frac{\underline{s}}{s_x}}\boldsymbol{\omega}_{x}\right) \cdot \mathbbm{1}_{{\boldsymbol\ell}_x}\left(2^{-\mathfrak{K}\frac{\underline{s}}{s_x}}\boldsymbol{\omega}_{x}\right) \cdot M_{\mathfrak{K},{\boldsymbol\ell}_o}(\mathbf o) \nonumber \\
    &= \epsilon_0 2^{-\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} \sum_{{\boldsymbol\ell}_o} \mathcal{F}[M_{\mathfrak{K},\boldsymbol{-\frac{\mathfrak{m}}{2}}}](\boldsymbol{\omega}_x) \cdot M_{\mathfrak{K},{\boldsymbol\ell}_o}(\mathbf o) \cdot \left(\sum_{{\boldsymbol\ell}_x}\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\mathbbm{1}_{{\boldsymbol\ell}_x}\left(2^{-\mathfrak{K}\frac{\underline{s}}{s_x}}\boldsymbol{\omega}_{x}\right) \right).
\end{align}   
Note that, for fixed ${\boldsymbol\ell}_o$,  $\boldsymbol{\omega}_x \mapsto \sum_{{\boldsymbol\ell}_x}\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\mathbbm{1}_{{\boldsymbol\ell}_x}(2^{-\mathfrak{K}\frac{\underline{s}}{s_x}}\boldsymbol{\omega}_{x})$ is the indicator function on
\begin{align*}
    \bigcup_{{\boldsymbol\ell}_x: \beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}>0} \bigtimes_{j=1}^{d_x}\left[1.1\pi 2^{\mathfrak{K}\frac{\underline{s}}{s_x}} + \zeta \ell_{x,j}, 1.1\pi 2^{\mathfrak{K}\frac{\underline{s}}{s_x}} + (\zeta \ell_{x,j} + 1)\right] ,
\end{align*}
The above observation as applied to the right hand side of Eq. \eqref{eq:fourier_f_v} means that we can apply \Cref{lem:new_besov_mask} to obtain
\begin{align} \|f_{\mathbf v}\|_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})} &\lesssim \epsilon_0 2^{-\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} \cdot  2^{\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} = \epsilon_0 .
\end{align}
\steve{Hence we can choose $\epsilon_0$ to be a small scalar such that $\|f_{\mathbf v}\|_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})} \leq 1$. The rest of the conditions that $f_{\mathbf v} \in L^\infty(\mathbb{R}^{d_x+d_o}) \cap L^1(\mathbb{R}^{d_x+d_o}) \cap C^0(\mathbb{R}^{d_x+d_o})$ are all trivial to verify. Therefore, $f_{\mathbf v}$ satisfies \Cref{ass:f_ast}. }

\underline{\emph{Step Four.}}
By the Gilbert-Varshamov Bound \cite{Tsybakov}[Lemma 2.9], for $|\mathcal{L}|\geq 8$, there exists a subset $V_\mathfrak{K}$ of $\{0,1\}^{|\mathcal{L}|}$ such that $\boldsymbol{0}\in V_\mathfrak{K}$ and
\begin{align} \sum_{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o}\left|\beta_{\mathbf v ({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} - \beta_{\mathbf v' ({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\right|^2 \geq \frac{|\mathcal{L}|}{8}
\end{align}
for $\mathbf v\neq \mathbf v'\in V_\mathfrak{K}$ and $|V_\mathfrak{K}|\geq 2^{\frac{|\mathcal{L}|}{8}}$. 
Note that since $\sqrt{p_X}$ is an even function over $[-1/2,1/2]^{d_x}$, its Fourier transform $q$ is a real valued function. Define
\begin{align} q(\boldsymbol{\omega}_x) := \mathcal{F}[\sqrt{p_{X}}](\boldsymbol{\omega}_x) , \quad
    \Tilde{q}(\boldsymbol{\omega}_x) := \mathcal{F}[\sqrt{p_X}](\boldsymbol{\omega}_x) 1_{[-\zeta/3, \zeta/3]^{d_x}}(\boldsymbol{\omega}_x).
\end{align}
For coefficients $\alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} \in \mathbb{R}$, we have
\begin{small}
\begin{align}
    &\left\|\sum_{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o} \alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\Omega_{\mathfrak{K}({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\right\|^2_{L^2(P_{XO})}\nonumber\\
    =& \int_{[0,1]^{d_o}}\int_{\mathbb{R}^{d_x}}\sum_{\substack{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o\nonumber\\ \Tilde{{\boldsymbol\ell}}_x, \Tilde{{\boldsymbol\ell}_o}}} \alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\alpha_{\mathbf v(\Tilde{{\boldsymbol\ell}_x}, \Tilde{{\boldsymbol\ell}}_o)} \Omega_{\mathfrak{K},{\boldsymbol\ell}_x}(\mathbf x)\Omega_{k\Tilde{{\boldsymbol\ell}}_x}(\mathbf x)M_{\mathfrak{K},{\boldsymbol\ell}_o}(\mathbf o)M_{k\Tilde{{\boldsymbol\ell}}_o}(\mathbf o)p_X(\mathbf x)\;\mathrm{d}\mathbf x\;\mathrm{d}\mathbf o\nonumber\\
    = & \int_{\mathbb{R}^{d_x}}\sum_{\substack{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o\\ \Tilde{{\boldsymbol\ell}}_x, \Tilde{{\boldsymbol\ell}_o}}} \alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\alpha_{\mathbf v(\Tilde{{\boldsymbol\ell}_x}, \Tilde{{\boldsymbol\ell}}_o)} \Omega_{\mathfrak{K},{\boldsymbol\ell}_x}(\mathbf x)\Omega_{k\Tilde{{\boldsymbol\ell}}_x}(\mathbf x) p_X(\mathbf x)\left(\int_{[0,1]^{d_o}}M_{\mathfrak{K},{\boldsymbol\ell}_o}(\mathbf o)M_{k\Tilde{{\boldsymbol\ell}}_o}(\mathbf o)\;\mathrm{d}\mathbf o\right)\;\mathrm{d}\mathbf x\nonumber\\
    \stackrel{(a)}{=} & \sum_{{\boldsymbol\ell}_o}\|M_{\mathfrak{K},{\boldsymbol\ell}_o}\|^2_{L^2(\mathbb{R}^{d_o})}\int_{\mathbb{R}^{d_x}} \left(\sum_{{\boldsymbol\ell}_x}\alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}(\mathbf x)\sqrt{p(\mathbf x)}\right)^2\;\mathrm{d}\mathbf x\nonumber\\
    \stackrel{(b)}{=} & \sum_{{\boldsymbol\ell}_o}\|M_{\mathfrak{K},{\boldsymbol\ell}_o}\|^2_{L^2(\mathbb{R}^{d_o})}\int_{\mathbb{R}^{d_x}} \left(\sum_{{\boldsymbol\ell}_x}\alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\mathcal{F}\left[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}\sqrt{p}\right](\boldsymbol{\omega}_x)\right)^2\;\mathrm{d}\boldsymbol{\omega}_x\nonumber\\
    =&2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\|M_{0\boldsymbol{0}}\|^2_{L^2(\mathbb{R}^{d_o})}\int_{\mathbb{R}^{d_x}} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x}\alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\mathcal{F}\left[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}\sqrt{p}\right](\boldsymbol{\omega}_x)\right)^2\;\mathrm{d}\boldsymbol{\omega}_x . \end{align}
\end{small}
where $(a)$ follows from the fact that $M_{\mathfrak{K},{\boldsymbol\ell}_o}$ have pairwise disjoint support verified in \underline{\emph{Step Two}} above; and $(b)$ follows from the Plancherel's Theorem. By Eq. \eqref{eq: gen_coeff_prob_l2}, we have
\begin{align} &\quad \|f_{\mathbf v} - f_{\mathbf v'}\|_{L^2(P_{XO})}^2 \nonumber \\
    &= \epsilon_0 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} 2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\|M_{0\boldsymbol{0}}\|_{L^2(\mathbb{R}^{d_o})}^2 \nonumber \\
    &\qquad \cdot \int_{\mathbb{R}^{d_x}} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x}\left(\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} - \beta_{\mathbf v'({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\right)\mathcal{F}\left[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}\sqrt{p_X}\right](\boldsymbol{\omega}_x)\right)^2\;\mathrm{d}\boldsymbol{\omega}_x \nonumber \\
    &\geq \epsilon_0 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} 2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\|M_{0\boldsymbol{0}}\|_{L^2(\mathbb{R}^{d_o})}^2\left((A)^2/2 - (B)^2\right),
\end{align}
where the last step follows from the reverse triangular inequality $(a+b)^2 \geq \frac{a^2}{2} - b^2$, and we define
\begin{align*}
    (A)^2&:= \sum_{{\boldsymbol\ell}_o}\left\|\sum_{{\boldsymbol\ell}_x}\left(\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} - \beta_{\mathbf v'({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\right) \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]  \ast \Tilde{q}\right\|_{L^2(\mathbb{R}^{d_x})}^2\\
    (B)^2&:=\sum_{{\boldsymbol\ell}_o}\left\|\sum_{{\boldsymbol\ell}_x}\left(\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} - \beta_{\mathbf v'({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\right)  \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]   \ast (q-\Tilde{q})\right\|_{L^2(\mathbb{R}^{d_x})}^2.
\end{align*}
In order to lower bound Eq.~\eqref{eq:L2_norm_A_B}, we need to lower bound $(A)^2$ and upper bound $(B)^2$.
First, we are going to lower bound $(A)^2$.
From Eq.~\eqref{eq:fourier_omega_k_lx}, we know that the support of $\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]$ is 
\begin{align} \tilde{I_{{\boldsymbol\ell}_x}} := \bigtimes_{j=1}^{d_x}\left[1.1\pi 2^{\mathfrak{K} \frac{\underline{s}}{s_x}} + \zeta \ell_{x,j}, 1.1\pi 2^{\mathfrak{K} \frac{\underline{s}}{s_x}} + (\zeta \ell_{x,j} + 1)\right].
\end{align}
Since the support of $\Tilde{q}$ is $[-\zeta/3, \zeta/3]^{d_x}$, by the standard fact that $\mathrm{supp}(f\ast g)\subseteq \mathrm{supp}(f) + \mathrm{supp}(g)$, we have
\begin{align} \mathrm{supp}\left( \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]  \ast \Tilde{q} \right) &\subseteq \bigtimes_{j=1}^{d_x}\left[1.1\pi 2^{\mathfrak{K} \frac{\underline{s}}{s_x}} + \zeta (\ell_{x,j} - 1/3), 1.1\pi 2^{\mathfrak{K} \frac{\underline{s}}{s_x}} + (\zeta (\ell_{x,j} + 1/3) + 1)\right] \nonumber \\
    &=: \Lambda_\mathfrak{K}
\end{align}
Note that for $\zeta \geq 3$, we have $\zeta(\ell_j + 1/3) + 1 \leq \zeta(\ell_j + 1 - 1/3)$, hence $\mathrm{supp}\left( \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]  \ast \Tilde{q} \right)$ is pairwise disjoint with respect to different ${\boldsymbol\ell}_x$. 
Hence we obtain that
\begin{align*}
    (A)^2 &= \sum_{{\boldsymbol\ell}_o}\sum_{{\boldsymbol\ell}_x}(\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} - \beta_{\mathbf v'({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)})^2 \left\| \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]   \ast \Tilde{q}\right\|^2_{L^2(\mathbb{R}^{d_x})}.
\end{align*}
Notice that
\begin{align} &\quad \left\|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]   \ast \Tilde{q}\right\|_{L^2(\mathbb{R}^{d_x})}^2 \nonumber \\
    &= \int_{\Lambda_\mathfrak{K}} \left|\int_{\mathbb{R}^{d_x}} \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}](\boldsymbol{\omega}_x^\prime) \tilde{q}(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime) \;\mathrm{d}\boldsymbol{\omega}_x^\prime\right|^2 \;\mathrm{d}\boldsymbol{\omega}_x \nonumber \\
    &= 2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}} \int_{\Lambda_\mathfrak{K}} \left|\int_{\mathbb{R}^{d_x}} \mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}]\left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}} \boldsymbol{\omega}_x^\prime \right) \cdot \mathbbm{1}_{{\boldsymbol\ell}_x} \left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}} \boldsymbol{\omega}_x^\prime \right) \cdot \tilde{q}(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime) \;\mathrm{d}\boldsymbol{\omega}_x^\prime\right|^2 \;\mathrm{d}\boldsymbol{\omega}_x \nonumber \\
    &\stackrel{(i)}{\geq} 2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}} \int_{\tilde{I_{{\boldsymbol\ell}_x}}} \left|\int_{\mathbb{R}^{d_x}} \mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}]\left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}} \boldsymbol{\omega}_x^\prime \right) \cdot \mathbbm{1}_{{\boldsymbol\ell}_x} \left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}} \boldsymbol{\omega}_x^\prime \right) \cdot \tilde{q}(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime) \;\mathrm{d}\boldsymbol{\omega}_x^\prime\right|^2 \;\mathrm{d}\boldsymbol{\omega}_x \nonumber \\
    &\stackrel{(ii)}{=} 2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}} \int_{\tilde{I_{{\boldsymbol\ell}_x}}} \left|\int_{\tilde{I_{{\boldsymbol\ell}_x}}} \mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}]\left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}} \boldsymbol{\omega}_x^\prime \right) \cdot \tilde{q}(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime) \;\mathrm{d}\boldsymbol{\omega}_x^\prime\right|^2 \;\mathrm{d}\boldsymbol{\omega}_x .
\end{align}
$(i)$ above holds because $\tilde{I_{{\boldsymbol\ell}_x}} \subset \Lambda_\mathfrak{K}$; and $(ii)$ holds because of the indicator function.
Notice, for any $\boldsymbol{\omega}_x,  \boldsymbol{\omega}_x^\prime \in \tilde{I_{{\boldsymbol\ell}_x}}$, we have for $j \in \{1, \ldots, d_x\}$, $
1 \geq \boldsymbol{\omega}_{x, j} - \boldsymbol{\omega}^\prime_{x, j} \geq -1$. 
Since for any $-1 \leq t \leq 1$, $i \in \{1, \ldots, d_x\}$ and $g$ defined in Eq.~\eqref{eq:p_X_bump}, there is $\mathcal{F}[\sqrt{g}](t) = \int_{-1/2}^{1/2} \sqrt{g}(x_i) \exp(-x_i t)dx_i = \int_{-1/2}^{1/2} \sqrt{g}(x_i) \cos( x_i t) dx_i > 0$.
So we have, for $\zeta > 3$,
\begin{align*}
    \tilde{q}(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime) = q(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime)= \mathcal{F}[\sqrt{p_X}](\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime) =\prod_{i=1}^{d_x} \mathcal{F}[\sqrt{g}](\boldsymbol{\omega}_{x,i} - \boldsymbol{\omega}^\prime_{x,i}) > 0.
\end{align*}
Since both $\mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}] (2^{-\frac{\mathfrak{K}\underline{s}}{s_x}} \boldsymbol{\omega}_x^\prime)$ and $\tilde{q}(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime)$ are positive and real, we continue from Eq.~\eqref{eq:F_conv_tilde_q_1} to have
\begin{align*}
    \geq 2^{-\frac{2 \mathfrak{K}\underline{s}d_x}{s_x}} \left( \inf_{\boldsymbol{\omega}_x \in I_{{\boldsymbol\ell}_x}} \mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}] (\boldsymbol{\omega}_x) \right)^2 \cdot \underbrace{\int_{\tilde{I_{{\boldsymbol\ell}_x}}} \left( \int_{\tilde{I_{{\boldsymbol\ell}_x}}} \tilde{q}\left( \boldsymbol{\omega}_x - \boldsymbol{\omega}_x^{\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_x^{\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_x}_{(\ast)} .
\end{align*}
Notice that in the integration in the term $(\ast)$ above, only the difference of $\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^{\prime}$ show up. 
So we can obtain
\begin{align*}
    (\ast) &= \int_{[0,1]^{d_x}} \left( \int_{[0,1]^{d_x}} \tilde{q}\left( \boldsymbol{\omega}_x - \boldsymbol{\omega}_x^{\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_x^{\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_x \\
    &= \prod_{i=1}^{d_x} \int_{0}^{1} \left( \int_0^1  \tilde{q}_i\left( \boldsymbol{\omega}_{x, i} - \boldsymbol{\omega}_{x, i}^{\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_{x, i}^{\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_{x, i} \\
    &= \prod_{i=1}^{d_x} \int_{0}^{1} \left( \int_{\boldsymbol{\omega}_{x, i}-1}^{\boldsymbol{\omega}_{x, i}} \tilde{q}_i\left( \boldsymbol{\omega}_{x, i}^{\prime\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_{x, i}^{\prime\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_{x, i} \\
    &= \prod_{i=1}^{d_x} \int_{0}^{1} \left( \int_{\boldsymbol{\omega}_{x, i}-1}^{\boldsymbol{\omega}_{x, i}} q_i\left( \boldsymbol{\omega}_{x, i}^{\prime\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_{x, i}^{\prime\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_{x, i}.
\end{align*}
The second last equality holds by change of variables, and the last equality holds because $\tilde{q}_i(\omega)=q_i(\omega)$ for $\omega \in [-\zeta/3, \zeta/3]$. 
So $(\ast)$ is a strictly positive constant independent of $\zeta, k, n$. Plugging it back to above, we obtain
\begin{align*}
    \left\|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}] \ast \Tilde{q}\right\|_{L^2(\mathbb{R}^{d_x})}^2 \geq 2^{-\frac{2 \mathfrak{K}\underline{s}d_x}{s_x}} \left( \inf_{\boldsymbol{\omega}_x \in I_{{\boldsymbol\ell}_x}} \mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}](\boldsymbol{\omega}_x) \right)^2 \cdot (\ast). 
\end{align*}
Notice that, since $I_{{\boldsymbol\ell}_x}\subseteq [1.1\pi, 1.95\pi]^{d_x}$ and we use Eq.~\eqref{eq:fourier_M00} to obtain, since $M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}$ is an even function and thus has real-valued Fourier transform
\begin{align*}
    \inf_{\boldsymbol{\omega}_x \in I_{{\boldsymbol\ell}_x}} \left| \mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}](\boldsymbol{\omega}_x) \right|^2 = \inf_{\boldsymbol{\omega}_x \in I_{{\boldsymbol\ell}_x}} \left| \prod_{i=1}^{d_x} \frac{\sin(\boldsymbol{\omega}_{x,i}/2)^{\mathfrak{m}}}{ (\boldsymbol{\omega}_{x,i}/2)^{\mathfrak{m}}} \right|^2 \geq \inf_{\omega\in [1.1\pi, 1.95\pi]} \left( \frac{\sin(\omega/2)}{\omega/2} \right)^{2\mathfrak{m}d_x} > 0.
\end{align*}
Define the following positive constant, independent of $\zeta$, $k$ or $n$,
\begin{align} C_{\chi} :=  (\ast) \cdot \inf_{\omega\in [1.1\pi, 1.95\pi]} \left( \frac{\sin(\omega/2)}{\omega/2} \right)^{2\mathfrak{m}d_x} .
\end{align}
We thus have
\begin{align} \left\|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}] \ast \Tilde{q}\right\|_{L^2(\mathbb{R}^{d_x})}^2 \geq C_{\chi} 2^{-2\mathfrak{K}\underline{s}\frac{d_x}{s_x}}. 
\end{align}
Therefore,
\begin{align*}
    (A)^2 &\geq \sum_{{\boldsymbol\ell}_o,{\boldsymbol\ell}_x}(\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} - \beta_{\mathbf v'({\boldsymbol\ell}_x',{\boldsymbol\ell}_o')})^2 C_{\chi}2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}} \stackrel{(a)}{\geq} \frac{C_{\chi}}{8}|\mathcal{L}| 2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}} \stackrel{(b)}{\gtrsim} \zeta^{-d_x}2^{-\mathfrak{K}\underline{s}\left(\frac{d_x}{s_x} - \frac{d_o}{s_o}\right)}.
\end{align*}
where $(a)$ follows from Eq. \eqref{eq: gv_beta_sep} and $(b)$ follows from Eq.~\eqref{eq:size_L}.

Next, we are going to upper bound $(B)$.
We have
\begin{align}
    (B)^2 &\leq \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x}\left\|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]\ast (q-\Tilde{q})\right\|_{L^2(\mathbb{R}^{d_x})}\right)^2\nonumber\\
    &\stackrel{(a)}{\leq} \|q - \Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x} \|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]\|_{L^2(\mathbb{R}^{d_x})}\right)^2 \nonumber\\
    &\stackrel{(b)}{\leq} \|q - \Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x} \|M_{\mathfrak{K},\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_x})}\right)^2 \nonumber\\
    &\stackrel{(c)}{=} \|q - \Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x} 2^{-\mathfrak{K}\frac{\underline{s}d_x}{2s_x}} \|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_x})}\right)^2 \nonumber\\
    &=  \|q - \Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x}1 \right)^2  2^{-\mathfrak{K}\frac{\underline{s}d_x}{s_x}}\|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_x})}^2\nonumber\\
    &\lesssim  \|q - \Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})} \zeta^{-2d_x}2^{\mathfrak{K}\underline{s}\left(\frac{2d_x}{s_x} + \frac{d_o}{s_o}\right)} 2^{-\mathfrak{K}\frac{\underline{s}d_x}{s_x}}\|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_x})}^2\nonumber\\
    &\stackrel{(d)}{\leq} \|q - \Tilde{q}\|_{L^1(\mathbb{R}^{d_x})}^2 \zeta^{-\frac{1}{2}d_x} 2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o}}2^{\frac{\mathfrak{K}\underline{s}d_x}{s_x}} \|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_x})}^2 \end{align}
In the above derivations, $(a)$ holds by Young's convolution inequality, $(b)$ holds by Plancherel's Theorem and Eq.~\eqref{eq:fourier_omega_k_lx}, $(c)$ holds by the change of variables $\mathbf x\leftarrow 2^{-\frac{\mathfrak{K}\underline{s}}{s_x}}\mathbf x$, and $(d)$ holds for $\zeta\geq 1$. 
We have
\begin{align}
    \|q - \Tilde{q}\|_{L^1(\mathbb{R}^{d_x})} &= \int_{\mathbb{R}^{d_x}} \left|q(\boldsymbol{\omega}_x) - \Tilde{q}(\boldsymbol{\omega}_x)\right| \;\mathrm{d}\boldsymbol{\omega}_x \nonumber\\
    &\stackrel{(i)}{=} 2^{d_x} \prod_{i=1}^{d_x} \int_{\zeta/3}^{\infty} \left|\mathcal{F}[\sqrt{g}](\boldsymbol{\omega}_{x,i}) \right| \;\mathrm{d} \boldsymbol{\omega}_{x,i}\nonumber \\
    &\stackrel{(ii)}{\asymp} \prod_{i=1}^{d_x} \int_{\zeta/3}^{\infty} \boldsymbol{\omega}_{x,i}^{-3/4} \exp(-\sqrt{\boldsymbol{\omega}_{x,i}}) \;\mathrm{d}\boldsymbol{\omega}_x \nonumber\\
    &\leq \zeta^{-\frac{3}{4}d_x} \prod_{i=1}^{d_x}  \int_{\zeta}^\infty \exp(-\sqrt{\boldsymbol{\omega}_{x,i}}) \;\mathrm{d}\boldsymbol{\omega}_{x,i} \nonumber \\
    &= \zeta^{-\frac{3}{4}d_x} 2^{d_x}\left(1+\zeta^{1 / 2}\right)^{d_x} \exp\left(-d_x \zeta^{\frac{1}{2}}\right) \nonumber \\
    &\leq 2^{2d_x} \zeta^{-\frac{1}{4}d_x} \exp\left(-d_x \zeta^{\frac{1}{2}}\right), \end{align}
where in $(i)$ we use the definition of $\tilde{q}$ in Eq.~\eqref{eq:defi_tilde_q}; and in $(ii)$
we use the asymptotic decay of the Fourier transform of the bump function~\citep[Section 2]{johnson2015saddle}. 
\begin{align} \left|\mathcal{F}[\sqrt{g}](\omega) \right| \asymp \omega^{-3/4} \exp(-\sqrt{\omega}), \quad \omega \gg 1.
\end{align}
Hence, we plug Eq.~\eqref{eq:q_qt_diff} back to Eq.~\eqref{eq: b_upper_bound} and we find that
\begin{align} (B)^2 &\lesssim \zeta^{-\frac{1}{2}d_x} 2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o} + \frac{\mathfrak{K}\underline{s}d_x}{s_x}}\left(2^{2d_x} \zeta^{-\frac{1}{4}d_x} \exp\left(-d_x \zeta^{\frac{1}{2}}\right)\right)^2 \|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_x})}^2\nonumber\\ &\lesssim 2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o} + \frac{\mathfrak{K}\underline{s}d_x}{s_x}} \zeta^{-d_x} \exp\left(-2 d_x \zeta^{\frac{1}{2}}\right).
\end{align}
Hence in order for $(B)^2\leq (A)^2/4$ to hold, a sufficient condition on $\zeta$ is given by the following inequality, up to some constants,
\begin{align}
    &2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o} + \frac{\mathfrak{K}\underline{s}d_x}{s_x}} \zeta^{-d_x}\exp\left(-2 d_x \zeta^{\frac{1}{2}}\right)  \lesssim \frac{1}{4} \zeta^{-d_x}2^{-\frac{\mathfrak{K}\underline{s}d_x}{s_x}}2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\nonumber\\
    \iff \qquad\qquad & \exp\left(-2 d_x \zeta^{\frac{1}{2}}\right) \lesssim 2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}}. \end{align}
Hence for sufficiently large $\zeta = \zeta(n)$, such that Eq. \eqref{eq:zeta_one} is satisfied, we have $(A)\geq (B)/2$, thus 
\begin{align} \|f_{\mathbf v} - f_{\mathbf v'}\|^2_{L^2(P_{XO})} & \geq \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} 2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_o})}^2 \frac{1}{4}(A)^2\nonumber\\
    &\gtrsim \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} 2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\zeta^{-d_x}2^{-\frac{\mathfrak{K}\underline{s}d_x}{s_x}}2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\nonumber\\
    &= \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}}\zeta^{-d_x}.
\end{align}

\underline{\emph{Step Four.}}
By the Gilbert-Varshamov Bound \cite{Tsybakov}[Lemma 2.9], for $|\mathcal{L}|\geq 8$, there exists a subset $V_\mathfrak{K}$ of $\{0,1\}^{|\mathcal{L}|}$ such that $\boldsymbol{0}\in V_\mathfrak{K}$ and
\begin{align} \sum_{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o}\left|\beta_{\mathbf v ({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} - \beta_{\mathbf v' ({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\right|^2 \geq \frac{|\mathcal{L}|}{8}
\end{align}
for $\mathbf v\neq \mathbf v'\in V_\mathfrak{K}$ and $|V_\mathfrak{K}|\geq 2^{\frac{|\mathcal{L}|}{8}}$. 
Note that since $\sqrt{p_X}$ is an even function over $[-1/2,1/2]^{d_x}$, its Fourier transform $q$ is a real valued function. Define
\begin{align} q(\boldsymbol{\omega}_x) := \mathcal{F}[\sqrt{p_{X}}](\boldsymbol{\omega}_x) , \quad
    \Tilde{q}(\boldsymbol{\omega}_x) := \mathcal{F}[\sqrt{p_X}](\boldsymbol{\omega}_x) 1_{[-\zeta/3, \zeta/3]^{d_x}}(\boldsymbol{\omega}_x).
\end{align}
For coefficients $\alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} \in \mathbb{R}$, we have
\begin{small}
\begin{align}
    &\left\|\sum_{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o} \alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\Omega_{\mathfrak{K}({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\right\|^2_{L^2(P_{XO})}\nonumber\\
    =& \int_{[0,1]^{d_o}}\int_{\mathbb{R}^{d_x}}\sum_{\substack{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o\nonumber\\ \Tilde{{\boldsymbol\ell}}_x, \Tilde{{\boldsymbol\ell}_o}}} \alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\alpha_{\mathbf v(\Tilde{{\boldsymbol\ell}_x}, \Tilde{{\boldsymbol\ell}}_o)} \Omega_{\mathfrak{K},{\boldsymbol\ell}_x}(\mathbf x)\Omega_{k\Tilde{{\boldsymbol\ell}}_x}(\mathbf x)M_{\mathfrak{K},{\boldsymbol\ell}_o}(\mathbf o)M_{k\Tilde{{\boldsymbol\ell}}_o}(\mathbf o)p_X(\mathbf x)\;\mathrm{d}\mathbf x\;\mathrm{d}\mathbf o\nonumber\\
    = & \int_{\mathbb{R}^{d_x}}\sum_{\substack{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o\\ \Tilde{{\boldsymbol\ell}}_x, \Tilde{{\boldsymbol\ell}_o}}} \alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\alpha_{\mathbf v(\Tilde{{\boldsymbol\ell}_x}, \Tilde{{\boldsymbol\ell}}_o)} \Omega_{\mathfrak{K},{\boldsymbol\ell}_x}(\mathbf x)\Omega_{k\Tilde{{\boldsymbol\ell}}_x}(\mathbf x) p_X(\mathbf x)\left(\int_{[0,1]^{d_o}}M_{\mathfrak{K},{\boldsymbol\ell}_o}(\mathbf o)M_{k\Tilde{{\boldsymbol\ell}}_o}(\mathbf o)\;\mathrm{d}\mathbf o\right)\;\mathrm{d}\mathbf x\nonumber\\
    \stackrel{(a)}{=} & \sum_{{\boldsymbol\ell}_o}\|M_{\mathfrak{K},{\boldsymbol\ell}_o}\|^2_{L^2(\mathbb{R}^{d_o})}\int_{\mathbb{R}^{d_x}} \left(\sum_{{\boldsymbol\ell}_x}\alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}(\mathbf x)\sqrt{p(\mathbf x)}\right)^2\;\mathrm{d}\mathbf x\nonumber\\
    \stackrel{(b)}{=} & \sum_{{\boldsymbol\ell}_o}\|M_{\mathfrak{K},{\boldsymbol\ell}_o}\|^2_{L^2(\mathbb{R}^{d_o})}\int_{\mathbb{R}^{d_x}} \left(\sum_{{\boldsymbol\ell}_x}\alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\mathcal{F}\left[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}\sqrt{p}\right](\boldsymbol{\omega}_x)\right)^2\;\mathrm{d}\boldsymbol{\omega}_x\nonumber\\
    =&2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\|M_{0\boldsymbol{0}}\|^2_{L^2(\mathbb{R}^{d_o})}\int_{\mathbb{R}^{d_x}} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x}\alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\mathcal{F}\left[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}\sqrt{p}\right](\boldsymbol{\omega}_x)\right)^2\;\mathrm{d}\boldsymbol{\omega}_x . \end{align}
\end{small}
where $(a)$ follows from the fact that $M_{\mathfrak{K},{\boldsymbol\ell}_o}$ have pairwise disjoint support verified in \underline{\emph{Step Two}} above; and $(b)$ follows from the Plancherel's Theorem. By Eq. \eqref{eq: gen_coeff_prob_l2}, we have
\begin{align} &\quad \|f_{\mathbf v} - f_{\mathbf v'}\|_{L^2(P_{XO})}^2 \nonumber \\
    &= \epsilon_0 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} 2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\|M_{0\boldsymbol{0}}\|_{L^2(\mathbb{R}^{d_o})}^2 \nonumber \\
    &\qquad \cdot \int_{\mathbb{R}^{d_x}} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x}\left(\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} - \beta_{\mathbf v'({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\right)\mathcal{F}\left[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}\sqrt{p_X}\right](\boldsymbol{\omega}_x)\right)^2\;\mathrm{d}\boldsymbol{\omega}_x \nonumber \\
    &\geq \epsilon_0 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} 2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\|M_{0\boldsymbol{0}}\|_{L^2(\mathbb{R}^{d_o})}^2\left((A)^2/2 - (B)^2\right),
\end{align}
where the last step follows from the reverse triangular inequality $(a+b)^2 \geq \frac{a^2}{2} - b^2$, and we define
\begin{align*}
    (A)^2&:= \sum_{{\boldsymbol\ell}_o}\left\|\sum_{{\boldsymbol\ell}_x}\left(\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} - \beta_{\mathbf v'({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\right) \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]  \ast \Tilde{q}\right\|_{L^2(\mathbb{R}^{d_x})}^2\\
    (B)^2&:=\sum_{{\boldsymbol\ell}_o}\left\|\sum_{{\boldsymbol\ell}_x}\left(\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} - \beta_{\mathbf v'({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\right)  \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]   \ast (q-\Tilde{q})\right\|_{L^2(\mathbb{R}^{d_x})}^2.
\end{align*}
In order to lower bound Eq.~\eqref{eq:L2_norm_A_B}, we need to lower bound $(A)^2$ and upper bound $(B)^2$.
First, we are going to lower bound $(A)^2$.
From Eq.~\eqref{eq:fourier_omega_k_lx}, we know that the support of $\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]$ is 
\begin{align} \tilde{I_{{\boldsymbol\ell}_x}} := \bigtimes_{j=1}^{d_x}\left[1.1\pi 2^{\mathfrak{K} \frac{\underline{s}}{s_x}} + \zeta \ell_{x,j}, 1.1\pi 2^{\mathfrak{K} \frac{\underline{s}}{s_x}} + (\zeta \ell_{x,j} + 1)\right].
\end{align}
Since the support of $\Tilde{q}$ is $[-\zeta/3, \zeta/3]^{d_x}$, by the standard fact that $\mathrm{supp}(f\ast g)\subseteq \mathrm{supp}(f) + \mathrm{supp}(g)$, we have
\begin{align} \mathrm{supp}\left( \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]  \ast \Tilde{q} \right) &\subseteq \bigtimes_{j=1}^{d_x}\left[1.1\pi 2^{\mathfrak{K} \frac{\underline{s}}{s_x}} + \zeta (\ell_{x,j} - 1/3), 1.1\pi 2^{\mathfrak{K} \frac{\underline{s}}{s_x}} + (\zeta (\ell_{x,j} + 1/3) + 1)\right] \nonumber \\
    &=: \Lambda_\mathfrak{K}
\end{align}
Note that for $\zeta \geq 3$, we have $\zeta(\ell_j + 1/3) + 1 \leq \zeta(\ell_j + 1 - 1/3)$, hence $\mathrm{supp}\left( \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]  \ast \Tilde{q} \right)$ is pairwise disjoint with respect to different ${\boldsymbol\ell}_x$. 
Hence we obtain that
\begin{align*}
    (A)^2 &= \sum_{{\boldsymbol\ell}_o}\sum_{{\boldsymbol\ell}_x}(\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} - \beta_{\mathbf v'({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)})^2 \left\| \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]   \ast \Tilde{q}\right\|^2_{L^2(\mathbb{R}^{d_x})}.
\end{align*}
Notice that
\begin{align} &\quad \left\|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]   \ast \Tilde{q}\right\|_{L^2(\mathbb{R}^{d_x})}^2 \nonumber \\
    &= \int_{\Lambda_\mathfrak{K}} \left|\int_{\mathbb{R}^{d_x}} \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}](\boldsymbol{\omega}_x^\prime) \tilde{q}(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime) \;\mathrm{d}\boldsymbol{\omega}_x^\prime\right|^2 \;\mathrm{d}\boldsymbol{\omega}_x \nonumber \\
    &= 2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}} \int_{\Lambda_\mathfrak{K}} \left|\int_{\mathbb{R}^{d_x}} \mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}]\left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}} \boldsymbol{\omega}_x^\prime \right) \cdot \mathbbm{1}_{{\boldsymbol\ell}_x} \left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}} \boldsymbol{\omega}_x^\prime \right) \cdot \tilde{q}(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime) \;\mathrm{d}\boldsymbol{\omega}_x^\prime\right|^2 \;\mathrm{d}\boldsymbol{\omega}_x \nonumber \\
    &\stackrel{(i)}{\geq} 2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}} \int_{\tilde{I_{{\boldsymbol\ell}_x}}} \left|\int_{\mathbb{R}^{d_x}} \mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}]\left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}} \boldsymbol{\omega}_x^\prime \right) \cdot \mathbbm{1}_{{\boldsymbol\ell}_x} \left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}} \boldsymbol{\omega}_x^\prime \right) \cdot \tilde{q}(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime) \;\mathrm{d}\boldsymbol{\omega}_x^\prime\right|^2 \;\mathrm{d}\boldsymbol{\omega}_x \nonumber \\
    &\stackrel{(ii)}{=} 2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}} \int_{\tilde{I_{{\boldsymbol\ell}_x}}} \left|\int_{\tilde{I_{{\boldsymbol\ell}_x}}} \mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}]\left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}} \boldsymbol{\omega}_x^\prime \right) \cdot \tilde{q}(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime) \;\mathrm{d}\boldsymbol{\omega}_x^\prime\right|^2 \;\mathrm{d}\boldsymbol{\omega}_x .
\end{align}

$(i)$ above holds because $\tilde{I_{{\boldsymbol\ell}_x}} \subset \Lambda_\mathfrak{K}$; and $(ii)$ holds because of the indicator function.
Notice, for any $\boldsymbol{\omega}_x,  \boldsymbol{\omega}_x^\prime \in \tilde{I_{{\boldsymbol\ell}_x}}$, we have for $j \in \{1, \ldots, d_x\}$, $
1 \geq \boldsymbol{\omega}_{x, j} - \boldsymbol{\omega}^\prime_{x, j} \geq -1$. 
Since for any $-1 \leq t \leq 1$, $i \in \{1, \ldots, d_x\}$ and $g$ defined in Eq.~\eqref{eq:p_X_bump}, there is $\mathcal{F}[\sqrt{g}](t) = \int_{-1/2}^{1/2} \sqrt{g}(x_i) \exp(-x_i t)dx_i = \int_{-1/2}^{1/2} \sqrt{g}(x_i) \cos( x_i t) dx_i > 0$.
So we have, for $\zeta > 3$,
\begin{align*}
    \tilde{q}(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime) = q(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime)= \mathcal{F}[\sqrt{p_X}](\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime) =\prod_{i=1}^{d_x} \mathcal{F}[\sqrt{g}](\boldsymbol{\omega}_{x,i} - \boldsymbol{\omega}^\prime_{x,i}) > 0.
\end{align*}
Since both $\mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}] (2^{-\frac{\mathfrak{K}\underline{s}}{s_x}} \boldsymbol{\omega}_x^\prime)$ and $\tilde{q}(\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^\prime)$ are positive and real, we continue from Eq.~\eqref{eq:F_conv_tilde_q_1} to have
\begin{align*}
    \geq 2^{-\frac{2 \mathfrak{K}\underline{s}d_x}{s_x}} \left( \inf_{\boldsymbol{\omega}_x \in I_{{\boldsymbol\ell}_x}} \mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}] (\boldsymbol{\omega}_x) \right)^2 \cdot \underbrace{\int_{\tilde{I_{{\boldsymbol\ell}_x}}} \left( \int_{\tilde{I_{{\boldsymbol\ell}_x}}} \tilde{q}\left( \boldsymbol{\omega}_x - \boldsymbol{\omega}_x^{\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_x^{\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_x}_{(\ast)} .
\end{align*}
Notice that in the integration in the term $(\ast)$ above, only the difference of $\boldsymbol{\omega}_x - \boldsymbol{\omega}_x^{\prime}$ show up. 
So we can obtain
\begin{align*}
    (\ast) &= \int_{[0,1]^{d_x}} \left( \int_{[0,1]^{d_x}} \tilde{q}\left( \boldsymbol{\omega}_x - \boldsymbol{\omega}_x^{\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_x^{\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_x \\
    &= \prod_{i=1}^{d_x} \int_{0}^{1} \left( \int_0^1  \tilde{q}_i\left( \boldsymbol{\omega}_{x, i} - \boldsymbol{\omega}_{x, i}^{\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_{x, i}^{\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_{x, i} \\
    &= \prod_{i=1}^{d_x} \int_{0}^{1} \left( \int_{\boldsymbol{\omega}_{x, i}-1}^{\boldsymbol{\omega}_{x, i}} \tilde{q}_i\left( \boldsymbol{\omega}_{x, i}^{\prime\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_{x, i}^{\prime\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_{x, i} \\
    &= \prod_{i=1}^{d_x} \int_{0}^{1} \left( \int_{\boldsymbol{\omega}_{x, i}-1}^{\boldsymbol{\omega}_{x, i}} q_i\left( \boldsymbol{\omega}_{x, i}^{\prime\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_{x, i}^{\prime\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_{x, i}.
\end{align*}
The second last equality holds by change of variables, and the last equality holds because $\tilde{q}_i(\omega)=q_i(\omega)$ for $\omega \in [-\zeta/3, \zeta/3]$. 
So $(\ast)$ is a strictly positive constant independent of $\zeta, k, n$. Plugging it back to above, we obtain
\begin{align*}
    \left\|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}] \ast \Tilde{q}\right\|_{L^2(\mathbb{R}^{d_x})}^2 \geq 2^{-\frac{2 \mathfrak{K}\underline{s}d_x}{s_x}} \left( \inf_{\boldsymbol{\omega}_x \in I_{{\boldsymbol\ell}_x}} \mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}](\boldsymbol{\omega}_x) \right)^2 \cdot (\ast). 
\end{align*}
Notice that, since $I_{{\boldsymbol\ell}_x}\subseteq [1.1\pi, 1.95\pi]^{d_x}$ and we use Eq.~\eqref{eq:fourier_M00} to obtain, since $M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}$ is an even function and thus has real-valued Fourier transform
\begin{align*}
    \inf_{\boldsymbol{\omega}_x \in I_{{\boldsymbol\ell}_x}} \left| \mathcal{F}[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}](\boldsymbol{\omega}_x) \right|^2 = \inf_{\boldsymbol{\omega}_x \in I_{{\boldsymbol\ell}_x}} \left| \prod_{i=1}^{d_x} \frac{\sin(\boldsymbol{\omega}_{x,i}/2)^{\mathfrak{m}}}{ (\boldsymbol{\omega}_{x,i}/2)^{\mathfrak{m}}} \right|^2 \geq \inf_{\omega\in [1.1\pi, 1.95\pi]} \left( \frac{\sin(\omega/2)}{\omega/2} \right)^{2\mathfrak{m}d_x} > 0.
\end{align*}
Define the following positive constant, independent of $\zeta$, $k$ or $n$,
\begin{align} C_{\chi} :=  (\ast) \cdot \inf_{\omega\in [1.1\pi, 1.95\pi]} \left( \frac{\sin(\omega/2)}{\omega/2} \right)^{2\mathfrak{m}d_x} .
\end{align}
We thus have
\begin{align} \left\|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}] \ast \Tilde{q}\right\|_{L^2(\mathbb{R}^{d_x})}^2 \geq C_{\chi} 2^{-2\mathfrak{K}\underline{s}\frac{d_x}{s_x}}. 
\end{align}
Therefore,
\begin{align*}
    (A)^2 &\geq \sum_{{\boldsymbol\ell}_o,{\boldsymbol\ell}_x}(\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)} - \beta_{\mathbf v'({\boldsymbol\ell}_x',{\boldsymbol\ell}_o')})^2 C_{\chi}2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}} \stackrel{(a)}{\geq} \frac{C_{\chi}}{8}|\mathcal{L}| 2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}} \stackrel{(b)}{\gtrsim} \zeta^{-d_x}2^{-\mathfrak{K}\underline{s}\left(\frac{d_x}{s_x} - \frac{d_o}{s_o}\right)}.
\end{align*}
where $(a)$ follows from Eq. \eqref{eq: gv_beta_sep} and $(b)$ follows from Eq.~\eqref{eq:size_L}.

Next, we are going to upper bound $(B)$.
We have
\begin{align}
    (B)^2 &\leq \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x}\left\|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]\ast (q-\Tilde{q})\right\|_{L^2(\mathbb{R}^{d_x})}\right)^2\nonumber\\
    &\stackrel{(a)}{\leq} \|q - \Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x} \|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]\|_{L^2(\mathbb{R}^{d_x})}\right)^2 \nonumber\\
    &\stackrel{(b)}{\leq} \|q - \Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x} \|M_{\mathfrak{K},\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_x})}\right)^2 \nonumber\\
    &\stackrel{(c)}{=} \|q - \Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x} 2^{-\mathfrak{K}\frac{\underline{s}d_x}{2s_x}} \|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_x})}\right)^2 \nonumber\\
    &=  \|q - \Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x}1 \right)^2  2^{-\mathfrak{K}\frac{\underline{s}d_x}{s_x}}\|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_x})}^2\nonumber\\
    &\lesssim  \|q - \Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})} \zeta^{-2d_x}2^{\mathfrak{K}\underline{s}\left(\frac{2d_x}{s_x} + \frac{d_o}{s_o}\right)} 2^{-\mathfrak{K}\frac{\underline{s}d_x}{s_x}}\|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_x})}^2\nonumber\\
    &\stackrel{(d)}{\leq} \|q - \Tilde{q}\|_{L^1(\mathbb{R}^{d_x})}^2 \zeta^{-\frac{1}{2}d_x} 2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o}}2^{\frac{\mathfrak{K}\underline{s}d_x}{s_x}} \|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_x})}^2 \end{align}
In the above derivations, $(a)$ holds by Young's convolution inequality, $(b)$ holds by Plancherel's Theorem and Eq.~\eqref{eq:fourier_omega_k_lx}, $(c)$ holds by the change of variables $\mathbf x\leftarrow 2^{-\frac{\mathfrak{K}\underline{s}}{s_x}}\mathbf x$, and $(d)$ holds for $\zeta\geq 1$. 
We have
\begin{align}
    \|q - \Tilde{q}\|_{L^1(\mathbb{R}^{d_x})} &= \int_{\mathbb{R}^{d_x}} \left|q(\boldsymbol{\omega}_x) - \Tilde{q}(\boldsymbol{\omega}_x)\right| \;\mathrm{d}\boldsymbol{\omega}_x \nonumber\\
    &\stackrel{(i)}{=} 2^{d_x} \prod_{i=1}^{d_x} \int_{\zeta/3}^{\infty} \left|\mathcal{F}[\sqrt{g}](\boldsymbol{\omega}_{x,i}) \right| \;\mathrm{d} \boldsymbol{\omega}_{x,i}\nonumber \\
    &\stackrel{(ii)}{\asymp} \prod_{i=1}^{d_x} \int_{\zeta/3}^{\infty} \boldsymbol{\omega}_{x,i}^{-3/4} \exp(-\sqrt{\boldsymbol{\omega}_{x,i}}) \;\mathrm{d}\boldsymbol{\omega}_x \nonumber\\
    &\leq \zeta^{-\frac{3}{4}d_x} \prod_{i=1}^{d_x}  \int_{\zeta}^\infty \exp(-\sqrt{\boldsymbol{\omega}_{x,i}}) \;\mathrm{d}\boldsymbol{\omega}_{x,i} \nonumber \\
    &= \zeta^{-\frac{3}{4}d_x} 2^{d_x}\left(1+\zeta^{1 / 2}\right)^{d_x} \exp\left(-d_x \zeta^{\frac{1}{2}}\right) \nonumber \\
    &\leq 2^{2d_x} \zeta^{-\frac{1}{4}d_x} \exp\left(-d_x \zeta^{\frac{1}{2}}\right), \end{align}
where in $(i)$ we use the definition of $\tilde{q}$ in Eq.~\eqref{eq:defi_tilde_q}; and in $(ii)$
we use the asymptotic decay of the Fourier transform of the bump function~\citep[Section 2]{johnson2015saddle}. 
\begin{align} \left|\mathcal{F}[\sqrt{g}](\omega) \right| \asymp \omega^{-3/4} \exp(-\sqrt{\omega}), \quad \omega \gg 1.
\end{align}
Hence, we plug Eq.~\eqref{eq:q_qt_diff} back to Eq.~\eqref{eq: b_upper_bound} and we find that
\begin{align} (B)^2 &\lesssim \zeta^{-\frac{1}{2}d_x} 2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o} + \frac{\mathfrak{K}\underline{s}d_x}{s_x}}\left(2^{2d_x} \zeta^{-\frac{1}{4}d_x} \exp\left(-d_x \zeta^{\frac{1}{2}}\right)\right)^2 \|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_x})}^2\nonumber\\ &\lesssim 2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o} + \frac{\mathfrak{K}\underline{s}d_x}{s_x}} \zeta^{-d_x} \exp\left(-2 d_x \zeta^{\frac{1}{2}}\right).
\end{align}
Hence in order for $(B)^2\leq (A)^2/4$ to hold, a sufficient condition on $\zeta$ is given by the following inequality, up to some constants,
\begin{align}
    &2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o} + \frac{\mathfrak{K}\underline{s}d_x}{s_x}} \zeta^{-d_x}\exp\left(-2 d_x \zeta^{\frac{1}{2}}\right)  \lesssim \frac{1}{4} \zeta^{-d_x}2^{-\frac{\mathfrak{K}\underline{s}d_x}{s_x}}2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\nonumber\\
    \iff \qquad\qquad & \exp\left(-2 d_x \zeta^{\frac{1}{2}}\right) \lesssim 2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}}. \end{align}
Hence for sufficiently large $\zeta = \zeta(n)$, such that Eq. \eqref{eq:zeta_one} is satisfied, we have $(A)\geq (B)/2$, thus 
\begin{align} \|f_{\mathbf v} - f_{\mathbf v'}\|^2_{L^2(P_{XO})} & \geq \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} 2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\|_{L^2(\mathbb{R}^{d_o})}^2 \frac{1}{4}(A)^2\nonumber\\
    &\gtrsim \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} 2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\zeta^{-d_x}2^{-\frac{\mathfrak{K}\underline{s}d_x}{s_x}}2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\nonumber\\
    &= \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}}\zeta^{-d_x}.
\end{align}

\underline{\emph{Step Five}}
Recall the distributions $P_{f_{\mathbf v}}$ defined above, and recall that $\boldsymbol{0}\in V_\mathfrak{K}$ for $V_\mathfrak{K}$ defined in Eq.~\eqref{eq: gv_beta_sep}. 
In this step, we are going to show that, for $P_{f_{\mathbf v}}^{\otimes n} := P_{f_{\mathbf v}} \otimes \dots \otimes P_{f_{\mathbf v}}$ which is a probability distribution over $(\mathcal{Z}\times \mathcal{O} \times\mathbb{R})^{n}$, it satisfies
\begin{align*}
    \frac{1}{|V_\mathfrak{K}|}\sum_{\mathbf v\in V_\mathfrak{K}}\operatorname{KL}\left(P_{f_{\mathbf v}}^{\otimes n}, P_{f_{\boldsymbol{0}}}^{\otimes n}   \right) \lesssim \epsilon_0^2 n  2^{-2\mathfrak{K}\frac{\underline{s}d_x}{s_x} \eta_1 -2\mathfrak{K}\underline{s}} .
\end{align*}
Notice that KL divergence tensorizes over independent copies at each dimension, we have that  $\operatorname{KL}(P_{f_{\boldsymbol{0}}}^{\otimes n} \| P_{f_{\mathbf v}}^{\otimes n}) = n \operatorname{KL}(P_{f_{\boldsymbol{0}}} \| P_{f_{\mathbf v}})$, so we are going to study $\operatorname{KL}(P_{f_{\boldsymbol{0}}} \| P_{f_{\mathbf v}})$ as follows.
\begin{align} \operatorname{KL}\left( P_{f_{\mathbf v}}, P_{f_{\boldsymbol{0}}} \right) &= \mathbb{E}_{(\mathbf z,\mathbf o) \sim P_{ZO}}\left[ \operatorname{KL}\left(  P_{f_{\mathbf v}} \left(\cdot \mid 
    \mathbf z,\mathbf o \right) \right) , P_{f_{\boldsymbol{0}}} \left( \cdot \mid \mathbf z,\mathbf o \right)\right] \nonumber\\
    &\stackrel{(a)}{=} \frac{ \left\|T f_{\mathbf v}\right\|_{L^2\left( P_{ZO} \right)}^2}{2 \sigma^2} \nonumber\\
    &\stackrel{(b)}{\leq} 2^{-2\mathfrak{K}\frac{\underline{s}d_x}{s_x} \eta_1} \frac{ \left\|f_{\mathbf v}\right\|_{L^2(P_{XO})}^2}{2 \sigma^2} 
\end{align}
In the above chain of derivations, 
we use \cite{blanchard2018optimal}[Proposition 6.2] in $(a)$; and in $(b)$ we use the \Cref{ass:T_contractivity} along with the fact from Eq.~\eqref{eq:fourier_f_v} that the support of the Fourier transform of $f_{\mathbf v}$ is indeed in high frequency.
\begin{align*}
    \mathrm{supp}(\mathcal{F}[f_{\mathbf v}]) = \cup_{{\boldsymbol\ell}_x, {\boldsymbol\ell}_o \in \mathcal{L}} \tilde{I}_{{\boldsymbol\ell}_x} \subseteq \left[ 1.1 \pi \cdot 2^{\mathfrak{K}\frac{\underline{s}}{s_x}}, 1.9\pi \cdot 2^{\mathfrak{K}\frac{\underline{s}}{s_x}} \right]^{d_x}.
\end{align*}
Next notice that, by Eq. \eqref{eq: gen_coeff_prob_l2}, we have
\begin{small}
\begin{align} &\|f_{\mathbf v}\|^2_{L^2(P_{XO})} \nonumber \\ &\stackrel{(a)}{\leq} \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} 2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\|M_{0,\boldsymbol{0}}\|^2_{L^2(\mathbb{R}^{d_o})}\int_{\mathbb{R}^{d_x}} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x}\beta_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\mathcal{F}\left[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}\sqrt{p}\right](\boldsymbol{\omega}_x)\right)^2\;\mathrm{d}\boldsymbol{\omega}_x \nonumber \\
    &\leq \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} 2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\|M_{0,\boldsymbol{0}}\|^2_{L^2(\mathbb{R}^{d_o})}\int_{\mathbb{R}^{d_x}} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x} \left| \mathcal{F}\left[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}\sqrt{p}\right](\boldsymbol{\omega}_x) \right| \right)^2\;\mathrm{d}\boldsymbol{\omega}_x \nonumber \\
    &\stackrel{(b)}{\lesssim} \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)} \int_{\mathbb{R}^{d_x}} \left(\sum_{{\boldsymbol\ell}_x} \left| \mathcal{F}\left[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}\sqrt{p}\right](\boldsymbol{\omega}_x) \right| \right)^2\;\mathrm{d}\boldsymbol{\omega}_x \nonumber \\
    &\leq \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)}  \left\|\sum_{{\boldsymbol\ell}_x} \left| \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}] \ast (q - \Tilde{q} + \Tilde{q}) \right| \right\|^2_{L^2(\mathbb{R}^{d_x})} \nonumber \\
    &\stackrel{(c)}{\leq} \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)}  \left(2\left\|\sum_{{\boldsymbol\ell}_x} \left|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]\ast (q-\Tilde{q}) \right| \right\|^2_{L^2(\mathbb{R}^{d_x})} + 2\left\|\sum_{{\boldsymbol\ell}_x} \left| \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]\ast \Tilde{q} \right| \right\|^2_{L^2(\mathbb{R}^{d_x})}\right) .
\end{align}
\end{small}
In the above derivations, $(a)$ holds by Eq. \eqref{eq: gen_coeff_prob_l2}, $(b)$ holds by $\sum_{{\boldsymbol\ell}_o}1 \lesssim 2^{\frac{\mathfrak{K}\underline{s}d_o}{s_o}}$, $(c)$ holds by triangular inequality. 
The first term in Eq.~\eqref{eq:f_v_L2} has already been upper bounded in Eq.~\eqref{eq:upper_B}. Hence for sufficiently large $\zeta$ that satisfies Eq.~\eqref{eq:zeta_one}, 
\begin{align*}
    \left\| \sum_{{\boldsymbol\ell}_x} \left| \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}]\ast (q-\Tilde{q}) \right| \right\|^2_{L^2(\mathbb{R}^{d_x})} &\lesssim 2^{\frac{\mathfrak{K}\underline{s}d_x}{s_x}} \zeta^{-\frac{d_x}{2}} \exp\left(-2 d_x \zeta^{\frac{1}{2}}\right)\\
    &\lesssim 2^{\frac{\mathfrak{K}\underline{s}d_x}{s_x}}2^{-\frac{2\mathfrak{K}\underline{s}d_x}{s_x}} = 2^{-\frac{\mathfrak{K}\underline{s}d_x}{s_x}}.
\end{align*}
The second term in Eq.~\eqref{eq:f_v_L2} can be upper bounded by
\begin{align*}
    \left\|\sum_{{\boldsymbol\ell}_x} \left| \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}] \ast \Tilde{q} \right| \right\|^2_{L^2(\mathbb{R}^{d_x})} &\stackrel{(a)}{\lesssim} \sum_{{\boldsymbol\ell}_x}\left\|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}] \ast \Tilde{q} \right\|^2_{L^2(\mathbb{R}^{d_x})}\\ &\stackrel{(b)}{\leq} \sum_{{\boldsymbol\ell}_x}\left\|\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}] \right\|^2_{L^2(\mathbb{R}^{d_x})} \cdot \|\Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})} \\
    &\stackrel{(c)}{\leq} \sum_{{\boldsymbol\ell}_x}\left\|\mathcal{F}[M_{\mathfrak{K},\boldsymbol{-\frac{\mathfrak{m}}{2}}}] \right\|^2_{L^2\left(\tilde{I}_{{\boldsymbol\ell}_x}\right)} \cdot \|\Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})}\\ &\leq \left\|\mathcal{F}[M_{\mathfrak{K},\boldsymbol{-\frac{\mathfrak{m}}{2}}}] \right\|^2_{L^2(\mathbb{R}^{d_x})} \cdot \|\Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})} \\
    &\stackrel{(d)}{=} \left\|M_{\mathfrak{K},\boldsymbol{-\frac{\mathfrak{m}}{2}}} \right\|^2_{L^2(\mathbb{R}^{d_x})} \cdot \|\Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})}\\ &\stackrel{(e)}{=} 2^{-\frac{\mathfrak{K}\underline{s}d_x}{s_x}} \left\|M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}} \right\|^2_{L^2(\mathbb{R}^{d_x})} \|\Tilde{q}\|^2_{L^1(\mathbb{R}^{d_x})}\\
    &\lesssim 2^{-\frac{\mathfrak{K}\underline{s}d_x}{s_x}}. 
\end{align*}
In the above chain of derivations, $(a)$ holds because $\mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}] \ast \Tilde{q}$ have disjoint support for different ${\boldsymbol\ell}_x$ proved in Eq.~\eqref{eq:support_F_conv_tilde_q}; $(b)$ holds by Young’s convolution inequality; $(c)$ holds by Eq. \eqref{eq:fourier_omega_k_lx}; $(d)$ holds by the fact that $I_{{\boldsymbol\ell}_x}$ are pairwise disjoint and Plancherel's Theorem and $(e)$ holds by change of variables $\mathbf x\leftarrow 2^{-\frac{\mathfrak{K}\underline{s}}{s_x}}\mathbf x$. 
Therefore, combining the upper bound on the above two terms, we obtain
\begin{align} \|f_{\mathbf v}\|^2_{L^2(P_{XO})} \lesssim \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}\left(1 - \frac{d_x}{2s_x}\right)}  2^{-\frac{\mathfrak{K}\underline{s}d_x}{s_x}} = \epsilon_0^2 2^{-2\mathfrak{K}\underline{s}} .
\end{align}
We plug the upper bound on $\|f_{\mathbf v}\|^2_{L^2(P_{XO})}$ back to Eq.~\eqref{eq:single_kl} to obtain
\begin{align} \operatorname{KL}\left(P_{f_{\mathbf v}}, P_{f_{\boldsymbol{0}}} \right) \lesssim \epsilon_0^2 \sigma^{-2} 2^{-2\mathfrak{K}\frac{\underline{s}d_x}{s_x} \eta_1 -2\mathfrak{K}\underline{s}}.
\end{align}
And thus,
\begin{align} \frac{1}{|V_\mathfrak{K}|}\sum_{\mathbf v\in V_\mathfrak{K}}\operatorname{KL}\left(P_{f_{\mathbf v}}^{\otimes n}, P_{f_{\boldsymbol{0}}}^{\otimes n} \right) \leq \epsilon_0^2 n\sigma^{-2} 2^{-2\mathfrak{K}\frac{\underline{s}d_x}{s_x} \eta_1 -2\mathfrak{K}\underline{s}}.
\end{align}

\underline{\emph{Step Six}}
In this step, we are going to show that, for any measurable learning method $(\mathbf z_i, \mathbf o_i,y_i)_{i=1}^n =: D \mapsto \hat{f}_D$, there is a distribution $P$ among $P_{f_{\mathbf v}}$ with $\mathbf v \in V_\mathfrak{K}$ which is difficult to learn for the considered learning method. We define a measurable mapping
\begin{align}
    \Psi:\left([0,1]^{d_z}\times[0,1]^{d_o}\times\mathbb{R}\right)^n \rightarrow V_\mathfrak{K}, \quad \Psi(D) := \underset{\mathbf v \in V_\mathfrak{K}}{\operatorname{argmin}} \left\| \hat{f}_D -f_{\mathbf v} \right\|_{L^2(P_{XO})} .
\end{align}
For $\mathbf v \in V_\mathfrak{K}$ and $D \in \left([0,1]^{d_z}\times[0,1]^{d_o}\times\mathbb{R}\right)^n $ with $\Psi(D) \neq \mathbf v$, we start from \eqref{eq:f_l2_separate} to have
\begin{align*}
    \epsilon_0 2^{-\mathfrak{K}\underline{s}} \zeta^{-\frac{d_x}{2}} &\lesssim \left\|f_{\Psi(D)} - f_{\mathbf v} \right\|_{L^2(P_{XO})}\\ &\leq\left\|f_{\Psi(D)} -\hat{f}_D \right\|_{L^2(P_{XO})} + \left\|\hat{f}_D - f_{\mathbf v} \right\|_{L^2(P_{XO})}\\ &\leq 2\left\|\hat{f}_D - f_{\mathbf v} \right\|_{L^2(P_{XO})} .
\end{align*}
Consequently, for all $\mathbf v \in V_\mathfrak{K}$ we find
\begin{align*}
    P_{f_{\mathbf v}}^{\otimes n}(D: \Psi(D) \neq \mathbf v) \leq P_{f_{\mathbf v}}^{\otimes n} \left(D:\left\|\hat{f}_D - f_{\mathbf v} \right\|_{L^2(P_{XO})} \gtrsim \epsilon_0 2^{-\mathfrak{K}\underline{s}} \zeta^{-\frac{d_x}{2}}\right) .
\end{align*}
Therefore, we have
\begin{align}
    &\max _{\mathbf v \in V_\mathfrak{K}} P_{f_{\mathbf v}}^{\otimes n} \left(D:\left\|\hat{f}_D - f_{\mathbf v} \right\|_{L^2(P_{XO})} \gtrsim \epsilon_0 2^{-\mathfrak{K}\underline{s}} \zeta^{-\frac{d_x}{2}}\right) \nonumber \\ 
    \geq & \max _{\mathbf v \in V_\mathfrak{K}} P_{f_{\mathbf v}}^{\otimes n}(D: \Psi(D) \neq \mathbf v) \nonumber \\
    \stackrel{(a)}{\gtrsim} & \frac{\sqrt{|V_\mathfrak{K}|}}{\sqrt{|V_\mathfrak{K}|} + 1} \left( 1 - \frac{\epsilon_0^2 n 2^{-2\mathfrak{K}\frac{\underline{s}d_x}{s_x} \eta_1} 2^{-2\mathfrak{K}\underline{s}} }{ \log |V_\mathfrak{K}| } -\frac{1}{2 \log |V_\mathfrak{K}|}\right) \nonumber \\
    \stackrel{(b)}{\geq} & \frac{\sqrt{|V_\mathfrak{K}|}}{\sqrt{|V_\mathfrak{K}|} + 1} \left( 1 - \frac{\epsilon_0^2 n2^{-2\mathfrak{K}\frac{\underline{s}d_x}{s_x} \eta_1}2^{-2\mathfrak{K}\underline{s}} }{\zeta^{-d_x}2^{\mathfrak{K}\frac{\underline{s}d_x}{s_x} + \mathfrak{K}\frac{\underline{s}d_o}{s_o}}}  -\frac{1}{2 \log |V_\mathfrak{K}|}\right) \nonumber \\
    \geq & \frac{\sqrt{|V_\mathfrak{K}|}}{\sqrt{|V_\mathfrak{K}|} + 1} \left( 1 - \epsilon_0^2 \zeta^{d_x} n 
    2^{-\mathfrak{K}\frac{\underline{s}}{s_x}\left(2d_x\eta_1 + 2s_x + d_x + \frac{d_o}{s_o}s_x\right)} -\frac{1}{2 \log |V_\mathfrak{K}|}\right). \end{align}
$(a)$ holds by \citet[Theorem 20]{fischer2020sobolev} and Eq. \eqref{eq:KL_upper_bound}. $(b)$ holds by the construction of $V_\mathfrak{K}$ in Eq.~\eqref{eq: gv_beta_sep} with $|V_\mathfrak{K}|\geq 2^{\frac{\mathcal{L}}{8}}$ so $\log |V_\mathfrak{K}|\gtrsim \zeta^{-d_x}2^{\mathfrak{K}\underline{s}(\frac{d_x}{s_x} + \frac{d_o}{s_o})}$. Next, we choose $\zeta$ and $k$ as the following function of $n$:
\begin{align}
\begin{aligned} \zeta = \left( \frac{1}{2} \frac{1}{2d_x\eta_1 + 2s_x + d_x + \frac{d_o}{s_o} s_x} \log n\right)^2, \quad 2^{-\mathfrak{K}\underline{s}} = n^{-\frac{s_x}{2d_x\eta_1 + 2s_x + d_x + \frac{d_o}{s_o} s_x}} \zeta^{-s_x} .
\end{aligned}
\end{align}
The choice of $\zeta$ ensures that Eq. \eqref{eq:zeta_one} is satisfied for sufficiently large $n\geq 1$. 
The choice of $k$ as a function of $n$ ensures that we can proceed from Eq.~\eqref{eq:V_k_lower_bound} to obtain
\begin{align*}
    &\quad \max _{\mathbf v \in V_\mathfrak{K}} P_{f_{\mathbf v}}^{\otimes n} \left(D: \left\| \hat{f}_D - f_{\mathbf v} \right\|_{L^2(P_{XO})} \geq \epsilon_0 n^{-\frac{s_x}{2s_x + 2d_x\eta_1 + d_x + \frac{d_o}{s_o}s_x}} (\log n)^{-2s_x - d_x} \right) \\
    &\gtrsim \frac{\sqrt{|V_\mathfrak{K}|}}{\sqrt{|V_\mathfrak{K}|} + 1} \left( 1 - \epsilon_0^2 - \frac{1}{2 \log |V_\mathfrak{K}|}\right) \\
    &\geq 1 - 2 \epsilon_0^2.
\end{align*}
The last inequality holds for sufficiently large $n$ because $ |V_\mathfrak{K}| \to \infty$ as $n \to \infty$.
We set $2\epsilon_0^2 = \tau^2$ and relabelling the constants, to obtain
\begin{align*}
    \inf_{D \mapsto \hat{f}_D} \sup_{f \in B_{2,q}^{s_x,s_o}\left(\mathbb{R}^{d_x+d_o}\right)} \left\| \hat{f}_D - f \right\|_{L^2(P_{XO})} &\geq \inf_{D \mapsto \hat{f}_D} \max_{\mathbf v \in V_\mathfrak{K}} \left\| \hat{f}_D - f_{\mathbf v}\right\|_{L^2(P_{XO})} \\
    &\geq \tau n^{-\frac{s_x}{2s_x + 2d_x\eta_1 + d_x + \frac{d_o}{s_o}s_x}} (\log n)^{-2s_x - d_x} \\
    &= \tau n^{-\frac{\frac{s_x}{d_x}}{1+2(\frac{s_x}{d_x}+\eta_1)+\frac{d_o}{s_o}\frac{s_x}{d_x}}} (\log n)^{-2s_x - d_x} ,
\end{align*}
holds for sufficiently large $n$ with probability $\geq 1 - C \tau^2$.

\underline{\emph{Step Six}}
In this step, we are going to show that, for any measurable learning method $(\mathbf z_i, \mathbf o_i,y_i)_{i=1}^n =: D \mapsto \hat{f}_D$, there is a distribution $P$ among $P_{f_{\mathbf v}}$ with $\mathbf v \in V_\mathfrak{K}$ which is difficult to learn for the considered learning method. We define a measurable mapping
\begin{align}
    \Psi:\left([0,1]^{d_z}\times[0,1]^{d_o}\times\mathbb{R}\right)^n \rightarrow V_\mathfrak{K}, \quad \Psi(D) := \underset{\mathbf v \in V_\mathfrak{K}}{\operatorname{argmin}} \left\| \hat{f}_D -f_{\mathbf v} \right\|_{L^2(P_{XO})} .
\end{align}
For $\mathbf v \in V_\mathfrak{K}$ and $D \in \left([0,1]^{d_z}\times[0,1]^{d_o}\times\mathbb{R}\right)^n $ with $\Psi(D) \neq \mathbf v$, we start from \eqref{eq:f_l2_separate} to have
